    //***** ファイルの読み込み *****//

    /// <summary>STBファイルの読み込み
    /// </summary>
    /// <param name="form">進捗状況を表示するForm(画面中央にゲージを表示)</param>
    /// <returns>エラーメッセージ</returns>
    internal string ReadFile(string stbFile, Form form = null, int gwidth = 0)
    {
        string errmsg = "";
        Stopwatch sw = new Stopwatch();


        // ファイルの確認
        if (!File.Exists(stbFile))
        {
            errmsg = "ファイルが見つかりません。" + "\r\n\r\n" + stbFile;
            return errmsg;
        }

        try
        {
            // 進捗ゲージの表示
            gaugeForm = null;
            if (form != null)
            {
                gaugeForm = form;
                sw.Start();
                GaugeShow(gwidth);
                GaugePercent(System.IO.Path.GetFileName(stbFile) + " 読み込み中", 0);
            }


            XmlDocument xml = new XmlDocument();
            element = "";

            do
            {
                // STBファイルを開く
                xml.Load(stbFile);

                if (xml.DocumentElement.Name.ToUpper() != "ST_BRIDGE")
                {
                    errmsg = "指定されたファイルは ST-Bridge のファイルではありません。" + "\r\n\r\n" + stbFile;
                    break;
                }
                else
                {
                    // 認識できないタグのリストを初期化
                    unknownList = new List<string>();


                    element = "ST_BRIDGEタグ(バージョン)";
                    string STBversion = getXmlElementAttribute(xml.DocumentElement, "version");
                    // バージョンチェック
                    string[] limitV = version.Split('.');
                    string[] fileV = STBversion.Split('.');
                    if (version != STBversion)
                    {
                        unknownListAdd("ST-Bridgeバージョン " + STBversion + " には対応していないため一部の情報を読み込めない可能性があります。\r\n(本システムはST-Bridgeバージョン " + version + " に対応しています)");
                        unknownListAdd("");
                    }
                    version = STBversion;


                    ReadFile_StbCommon(xml);
                    ReadFile_StbNodes(xml);
                    ReadFile_StbAxes(xml);
                    ReadFile_StbStories(xml);

                    StbModel.StbMembers = new StbModelClass.StbMembersClass();
                    ReadFile_StbColumns(xml);
                    ReadFile_StbPosts(xml);
                    ReadFile_StbGirders(xml);
                    ReadFile_StbBeams(xml);
                    ReadFile_StbBraces(xml);
                    ReadFile_StbSlabs(xml);
                    ReadFile_StbWalls(xml);
                    ReadFile_StbFootings(xml);
                    ReadFile_StbStrip_Footings(xml);
                    ReadFile_StbPiles(xml);
                    ReadFile_StbFoundationColumns(xml);
                    ReadFile_StbParapets(xml);

                    StbModel.StbSections = new StbModelClass.StbSectionsClass();
                    ReadFile_StbSecColumn_RC(xml);
                    ReadFile_StbSecColumn_S(xml);
                    ReadFile_StbSecColumn_SRC(xml);
                    ReadFile_StbSecColumn_CFT(xml);
                    ReadFile_StbSecBeam_RC(xml);
                    ReadFile_StbSecBeam_S(xml);
                    ReadFile_StbSecBeam_SRC(xml);
                    ReadFile_StbSecBrace_S(xml);
                    ReadFile_StbSecSlab_RC(xml);
                    ReadFile_StbSecSlab_Deck(xml);
                    //2016/09/06 Add Ver.1.4対応
                    ReadFile_StbSecSlab_Product(xml);
                    //Add End
                    ReadFile_StbSecWall_RC(xml);
                    ReadFile_StbSecFoundation_RC(xml);
                    ReadFile_StbSecPile_RC(xml);
                    ReadFile_StbSecOpen_RC(xml);
                    ReadFile_StbSecParapet_RC(xml);
                    ReadFile_StbSecSteel(xml);

                    ReadFile_StbSlabFrames(xml);

                    ReadFile_StbExtensions(xml);
                }
            } while (false);

            //解放
            xml = null;
        }
        catch (Exception ex)
        {
            errmsg = "エラーコード： " + ex.HResult + "\r\n" + ex.Message;
            if (element != "") errmsg += "\r\n\r\n" + element + "タグの読み込みでエラーが発生しました。";
        }
        finally
        {
            // 進捗ゲージの消去
            if (form != null)
            {
                do { Application.DoEvents(); } while (sw.ElapsedMilliseconds <= 1000); ;
                sw.Stop();
                GaugeClose();
            }
        }

        return errmsg;
    }


    #region ----- ファイル読み込みローカルルーチン -----

    private string getXmlElementAttribute(XmlElement xmlelem, string name)
    {
        string retcode = xmlelem.GetAttribute(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (retcode == "") retcode = xmlelem.GetAttribute(name.ToUpper());
            if (retcode == "") retcode = xmlelem.GetAttribute(name.ToLower());
            if (retcode == "")
            {
                for (int i = 0; i < xmlelem.Attributes.Count; i++)
                {
                    if (xmlelem.Attributes[i].Name.ToUpper() == name.ToUpper())
                    { retcode = xmlelem.Attributes[i].Value; break; }
                }
            }
        }
        return retcode;
    }
    private XmlNodeList getXmlNodeList(XmlDocument xml, string name)
    {
        XmlNodeList nodelist = xml.GetElementsByTagName(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (nodelist == null || nodelist.Count == 0) nodelist = xml.GetElementsByTagName(name.ToUpper());
            if (nodelist == null || nodelist.Count == 0) nodelist = xml.GetElementsByTagName(name.ToLower());
            if (nodelist == null || nodelist.Count == 0)
            {
                bool existflag = false;
                List<XmlNodeList> child = new List<XmlNodeList>();
                List<XmlNodeList> gchild = new List<XmlNodeList>();
                child.Add(xml.DocumentElement.ChildNodes);
                bool childflag = false;
                do
                {
                    childflag = false;
                    gchild = new List<XmlNodeList>();
                    for (int c = 0; c < child.Count; c++)
                    {
                        for (int i = 0; i < child[c].Count; i++)
                        {
                            if (child[c][i].Name.ToUpper() == name.ToUpper())
                            { nodelist = xml.DocumentElement.GetElementsByTagName(child[c][i].Name); existflag = true; break; }
                            if (child[c][i].ChildNodes.Count > 0)
                            {
                                childflag = true;
                                gchild.Add(child[c][i].ChildNodes);
                            }
                        }
                        if (existflag) break;
                    }
                    if (existflag) break;
                    if (gchild.Count > 0) child = gchild;
                } while (childflag);
            }
        }
        return nodelist;
    }
    private bool getXmlAttributeValueBool(XmlNode node, string name)
    {
        //
        // XML属性値の読み取り
        //
        bool retcode = false;
        XmlNode attr = node.Attributes.GetNamedItem(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToUpper());
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToLower());
            if (attr == null)
            {
                for (int i = 0; i < node.Attributes.Count; i++)
                {
                    if (node.Attributes[i].Name.ToUpper() == name.ToUpper())
                    { attr = node.Attributes.GetNamedItem(node.Attributes[i].Name); ; break; }
                }
            }
        }
        if (attr != null)
        {
            if (attr.Value.ToUpper() == "TRUE") retcode = true;
        }
        return retcode;
    }
    private double getXmlAttributeValueDouble(XmlNode node, string name)
    {
        //
        // XML属性値の読み取り
        //
        double retcode = 0;
        XmlNode attr = node.Attributes.GetNamedItem(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToUpper());
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToLower());
            if (attr == null)
            {
                for (int i = 0; i < node.Attributes.Count; i++)
                {
                    if (node.Attributes[i].Name.ToUpper() == name.ToUpper())
                    { attr = node.Attributes.GetNamedItem(node.Attributes[i].Name); ; break; }
                }
            }
        }

        //if (attr != null) retcode = double.Parse(attr.Value);
        if(attr != null)
        {
            if (!double.TryParse(attr.Value, out retcode)) { unknownListAdd(element + "[id=" + node.Attributes.GetNamedItem("id").Value + "]" + name + "に認識できない値があります。"); }
        }
            
        return retcode;
    }
    private int getXmlAttributeValueInt(XmlNode node, string name)
    {
        //
        // XML属性値の読み取り
        //
        int retcode = 0;
        XmlNode attr = node.Attributes.GetNamedItem(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToUpper());
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToLower());
            if (attr == null)
            {
                for (int i = 0; i < node.Attributes.Count; i++)
                {
                    if (node.Attributes[i].Name.ToUpper() == name.ToUpper())
                    { attr = node.Attributes.GetNamedItem(node.Attributes[i].Name); ; break; }
                }
            }
        }
        //if (attr != null) retcode = int.Parse(attr.Value);
        if (attr != null)
        {
           if(!int.TryParse(attr.Value, out retcode)) { unknownListAdd(element + "[id=" + node.Attributes.GetNamedItem("id").Value + "]" + name + "に認識できない値があります。"); }
        }
        return retcode;
    }
    private string getXmlAttributeValueString(XmlNode node, string name)
    {
        //
        // XML属性値の読み取り
        //
        string retcode = "";
        XmlNode attr = node.Attributes.GetNamedItem(name);
        if (!readUpLow)
        {
            // 大文字小文字を区別なく読み取る
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToUpper());
            if (attr == null) attr = node.Attributes.GetNamedItem(name.ToLower());
            if (attr == null)
            {
                for (int i = 0; i < node.Attributes.Count; i++)
                {
                    if (node.Attributes[i].Name.ToUpper() == name.ToUpper())
                    { attr = node.Attributes.GetNamedItem(node.Attributes[i].Name); ; break; }
                }
            }
        }
        if (attr != null) retcode = attr.Value;
        return retcode;
    }


    private void ReadFile_StbCommon(XmlDocument xml)
    {
        //
        // 共通情報の読み取り
        //
        element = "共通情報(StbCommon)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList common = getXmlNodeList(xml, "StbCommon");
        XmlNodeList reins = getXmlNodeList(xml, "StbReinforcement_Strength");


        if (common.Count > 0)
        {
            if (StbCommon == null) StbCommon = new StbCommonClass();
            StbCommon.globalID = getXmlAttributeValueString(common[0], "globalID");
            StbCommon.project_name = getXmlAttributeValueString(common[0], "project_name");
            StbCommon.app_name = getXmlAttributeValueString(common[0], "app_name");
            StbCommon.concrete_strength = getXmlAttributeValueString(common[0], "concrete_strength");
            StbCommon.steel_standard_code = getXmlAttributeValueString(common[0], "steel_standard_code");

            // 鉄筋強度
            if (StbCommon.StbReinforcement_Strength_List == null) StbCommon.StbReinforcement_Strength_List = new List<StbCommonClass.StbReinforcement_Strength>();
            if (reins.Count > 0)
            {
                for (int i = 0; i < reins.Count; i++)
                {
                    StbCommonClass.StbReinforcement_Strength rein = new StbCommonClass.StbReinforcement_Strength();
                    rein.D = getXmlAttributeValueString(reins[i], "D");
                    rein.SD = getXmlAttributeValueString(reins[i], "SD");
                    StbCommon.StbReinforcement_Strength_List.Add(rein);
                }
            }


            // 認識不可タグのチェック
            for (int i = 0; i < common.Count; i++)
            {
                //属性
                for (int j = 0; j < common[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(common[i].Attributes[j].Name, "globalID", true) == 0) diff = false;
                    if (string.Compare(common[i].Attributes[j].Name, "project_name", true) == 0) diff = false;
                    if (string.Compare(common[i].Attributes[j].Name, "app_name", true) == 0) diff = false;
                    if (string.Compare(common[i].Attributes[j].Name, "concrete_strength", true) == 0) diff = false;
                    if (string.Compare(common[i].Attributes[j].Name, "steel_standard_code", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + common[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < common[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(common[i].ChildNodes[k].Name, "StbReinforcement_Strength_List", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + common[i].ChildNodes[k].Name + "]");
                    //子子要素
                    for (int k2 = 0; k2 < common[i].ChildNodes[k].ChildNodes.Count; k2++)
                    {
                        diff = true;
                        if (string.Compare(common[i].ChildNodes[k].ChildNodes[k2].Name, "StbReinforcement_Strength", true) == 0) diff = false;
                        if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + common[i].ChildNodes[k].ChildNodes[k2].Name + "]");
                        //子子要素－属性
                        for (int j = 0; j < common[i].ChildNodes[k].ChildNodes[k2].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(common[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "D", true) == 0) diff = false;
                            if (string.Compare(common[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "SD", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + common[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name + "]");
                        }
                    }
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
    private void ReadFile_StbNodes(XmlDocument xml)
    {
        //
        // 節点情報の読み取り
        //
        element = "節点(StbNodes)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList nodes = getXmlNodeList(xml, "StbNode");


        if (StbModel.StbNodes == null) StbModel.StbNodes = new List<StbModelClass.StbNode>();

        // 節点
        if (nodes.Count > 0)
        {
            for (int i = 0; i < nodes.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(nodes.Count) * 100));
                StbModelClass.StbNode node = new StbModelClass.StbNode();
                node.id = getXmlAttributeValueInt(nodes[i], "id");
                node.x = getXmlAttributeValueDouble(nodes[i], "x");
                node.y = getXmlAttributeValueDouble(nodes[i], "y");
                node.z = getXmlAttributeValueDouble(nodes[i], "z");
                node.kind = getXmlAttributeValueString(nodes[i], "kind");
                node.id_member = getXmlAttributeValueInt(nodes[i], "id_member");
                StbModel.StbNodes.Add(node);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < nodes.Count; i++)
            {
                //属性
                for (int j = 0; j < nodes[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(nodes[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(nodes[i].Attributes[j].Name, "x", true) == 0) diff = false;
                    if (string.Compare(nodes[i].Attributes[j].Name, "y", true) == 0) diff = false;
                    if (string.Compare(nodes[i].Attributes[j].Name, "z", true) == 0) diff = false;
                    if (string.Compare(nodes[i].Attributes[j].Name, "kind", true) == 0) diff = false;
                    if (string.Compare(nodes[i].Attributes[j].Name, "id_member", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + nodes[i].Attributes[j].Name + "]");
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
    private void ReadFile_StbAxes(XmlDocument xml)
    {
        //
        // 軸情報の読み取り
