    private void ReadFile_StbSlabs(XmlDocument xml)
    {
        //
        // スラブ配置情報の読み取り
        //
        element = "スラブ(StbSlabs)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList slabs = getXmlNodeList(xml, "StbSlab");


        // スラブ配置
        if (slabs.Count > 0)
        {
            if (StbModel.StbMembers.StbSlabs == null) StbModel.StbMembers.StbSlabs = new List<StbModelClass.StbMembersClass.StbSlab>();
            for (int i = 0; i < slabs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(slabs.Count) * 100));
                StbModelClass.StbMembersClass.StbSlab slab = new StbModelClass.StbMembersClass.StbSlab();
                slab.id = getXmlAttributeValueInt(slabs[i], "id");
                slab.name = getXmlAttributeValueString(slabs[i], "name");
                slab.id_section = getXmlAttributeValueInt(slabs[i], "id_section");
                slab.kind_structure = getXmlAttributeValueString(slabs[i], "kind_structure");
                slab.kind_slab = getXmlAttributeValueString(slabs[i], "kind_slab");
                slab.level = getXmlAttributeValueDouble(slabs[i], "level");
                slab.thickness_ex_upper = getXmlAttributeValueDouble(slabs[i], "thickness_ex_upper");
                slab.thickness_ex_bottom = getXmlAttributeValueDouble(slabs[i], "thickness_ex_bottom");
                slab.dir_load = getXmlAttributeValueString(slabs[i], "dir_load");
                slab.angle_load = getXmlAttributeValueDouble(slabs[i], "angle_load");
                slab.isFoundation = getXmlAttributeValueBool(slabs[i], "isFoundation");
                slab.type_haunch = getXmlAttributeValueString(slabs[i], "type_haunch");

                //(子要素)
                //  (初期化)
                bool flag1 = false, flag2 = false, flag3 = false;
                for (int j = 0; j < slabs[i].ChildNodes.Count; j++)
                {
                    switch (slabs[i].ChildNodes[j].Name)
                    {
                        case "StbNodeid_List": flag1 = true; break;
                        case "StbSlabOffset_List": flag2 = true; break;
                        case "StbOpen": flag3 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
