                for (int j = 0; j < SecColumnRCs[i].ChildNodes.Count; j++)
                {
                    XmlNodeList Nodes = null;

                    bool flagSecFigure = false;
                    bool flagSecBar = false;

                    switch (SecColumnRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecFigure": flagSecFigure = true; break;
                        case "StbSecBar_Arrangement": flagSecBar = true; break;
                    }
