    private void ReadFile_StbSecColumn_S(XmlDocument xml)
    {
        //
        // S柱断面情報の読み取り
        //
        element = "S柱断面(StbSecColumn_S)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecColumnSs = getXmlNodeList(xml, "StbSecColumn_S");


        // S柱断面
        if (SecColumnSs.Count > 0)
        {
            if (StbModel.StbSections.StbSecColumns_S == null) StbModel.StbSections.StbSecColumns_S = new List<StbModelClass.StbSectionsClass.StbSecColumn_S>();
            for (int i = 0; i < SecColumnSs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecColumnSs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecColumn_S SecColumnS = new StbModelClass.StbSectionsClass.StbSecColumn_S();
                SecColumnS.id = getXmlAttributeValueInt(SecColumnSs[i], "id");
                SecColumnS.name = getXmlAttributeValueString(SecColumnSs[i], "name");
                SecColumnS.floor = getXmlAttributeValueString(SecColumnSs[i], "floor");
                SecColumnS.kind_column = getXmlAttributeValueString(SecColumnSs[i], "kind_column");
                SecColumnS.direction = getXmlAttributeValueBool(SecColumnSs[i], "direction");
                SecColumnS.base_type = getXmlAttributeValueString(SecColumnSs[i], "base_type");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecColumnSs[i].ChildNodes.Count; j++)
                {
                    bool flagSteelColumn = false;
                    bool flagBaseProduct = false;
                    switch (SecColumnSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelColumn": flagSteelColumn = true; break;
                        case "StbSecBaseProduct": flagBaseProduct = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecColumnSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELCOLUMN": flagSteelColumn = true; break;
                            case "STBSECBASEPRODUCT": flagBaseProduct = true; break;
                        }
                    }
                    if (flagSteelColumn) SecColumnS.StbSecSteelColumn = new StbModelClass.StbSectionsClass.StbSecColumn_S.StbSecSteelColumnClass[3];
                    if (flagBaseProduct) SecColumnS.StbSecBaseProduct = new StbModelClass.StbSectionsClass.StbSecColumn_S.StbSecBaseProductClass();
                }
                // (値セット)
                for (int j = 0; j < SecColumnSs[i].ChildNodes.Count; j++)
                {
                    XmlNode Node = null;

                    bool flagSteelColumn = false;
                    bool flagBaseProduct = false;
                    switch (SecColumnSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelColumn": flagSteelColumn = true; break;
                        case "StbSecBaseProduct": flagBaseProduct = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecColumnSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELCOLUMN": flagSteelColumn = true; break;
                            case "STBSECBASEPRODUCT": flagBaseProduct = true; break;
                        }
                    }
                    if (flagSteelColumn)
                    {
                        //--- 柱鉄骨 ---
                        Node = SecColumnSs[i].ChildNodes[j];
                        string pos = getXmlAttributeValueString(Node, "pos");
                        int TBs = 0, TBe = 2;
                        if (pos == "ALL") { TBs = 0; TBe = 2; }
                        if (pos == "BOTTOM") { TBs = 0; TBe = 0; }
                        if (pos == "CENTER") { TBs = 1; TBe = 1; }
                        if (pos == "TOP") { TBs = 2; TBe = 2; }
                        if (!readUpLow)
                        {
                            // 大文字小文字を区別なく読み取る
                            if (pos.ToUpper() == "ALL") { TBs = 0; TBe = 2; }
                            if (pos.ToUpper() == "BOTTOM") { TBs = 0; TBe = 0; }
                            if (pos.ToUpper() == "CENTER") { TBs = 1; TBe = 1; }
                            if (pos.ToUpper() == "TOP") { TBs = 2; TBe = 2; }
                        }
                        for (int TB = TBs; TB <= TBe; TB++)
                        {
                            SecColumnS.StbSecSteelColumn[TB] = new StbModelClass.StbSectionsClass.StbSecColumn_S.StbSecSteelColumnClass();
                            SecColumnS.StbSecSteelColumn[TB].pos = pos;
                            SecColumnS.StbSecSteelColumn[TB].shape = getXmlAttributeValueString(Node, "shape");
                            SecColumnS.StbSecSteelColumn[TB].strength_main = getXmlAttributeValueString(Node, "strength_main");
                            SecColumnS.StbSecSteelColumn[TB].strength_web = getXmlAttributeValueString(Node, "strength_web");
                        }
                    }
                    if (flagBaseProduct)
                    {
                        //--- 柱脚製品 ---
                        Node = SecColumnSs[i].ChildNodes[j];
                        SecColumnS.StbSecBaseProduct.product_company = getXmlAttributeValueString(Node, "product_company");
                        SecColumnS.StbSecBaseProduct.product_code = getXmlAttributeValueString(Node, "product_code");
                        break;
                    }
                }
                StbModel.StbSections.StbSecColumns_S.Add(SecColumnS);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < SecColumnSs.Count; i++)
            {
                //属性
                for (int j = 0; j < SecColumnSs[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "name", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "floor", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "kind_column", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "direction", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].Attributes[j].Name, "base_type", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnSs[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < SecColumnSs[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(SecColumnSs[i].ChildNodes[k].Name, "StbSecSteelColumn", true) == 0) diff = false;
                    if (string.Compare(SecColumnSs[i].ChildNodes[k].Name, "StbSecBaseProduct", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecColumnSs[i].ChildNodes[k].Name + "]");
                    //子要素－属性
                    if (string.Compare(SecColumnSs[i].ChildNodes[k].Name, "StbSecSteelColumn", true) == 0)
                    {
                        for (int j = 0; j < SecColumnSs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "pos", true) == 0) diff = false;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "shape", true) == 0) diff = false;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "strength_main", true) == 0) diff = false;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "strength_web", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnSs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                    if (string.Compare(SecColumnSs[i].ChildNodes[k].Name, "StbSecBaseProduct", true) == 0)
                    {
                        for (int j = 0; j < SecColumnSs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "product_company", true) == 0) diff = false;
                            if (string.Compare(SecColumnSs[i].ChildNodes[k].Attributes[j].Name, "product_code", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnSs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
