    private void ReadFile_StbSecColumn_CFT(XmlDocument xml)
    {
        //
        // CFT柱断面情報の読み取り
        //
        element = "CFT柱断面(StbSecColumn_CFT)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecColumnCFTs = getXmlNodeList(xml, "StbSecColumn_CFT");


        // CFT柱断面
        if (SecColumnCFTs.Count > 0)
        {
            if (StbModel.StbSections.StbSecColumns_CFT == null) StbModel.StbSections.StbSecColumns_CFT = new List<StbModelClass.StbSectionsClass.StbSecColumn_CFT>();
            for (int i = 0; i < SecColumnCFTs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecColumnCFTs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecColumn_CFT SecColumnCFT = new StbModelClass.StbSectionsClass.StbSecColumn_CFT();
                SecColumnCFT.id = getXmlAttributeValueInt(SecColumnCFTs[i], "id");
                SecColumnCFT.name = getXmlAttributeValueString(SecColumnCFTs[i], "name");
                SecColumnCFT.floor = getXmlAttributeValueString(SecColumnCFTs[i], "floor");
                SecColumnCFT.kind_column = getXmlAttributeValueString(SecColumnCFTs[i], "kind_column");
                SecColumnCFT.strength_concrete = getXmlAttributeValueString(SecColumnCFTs[i], "strength_concrete");
                SecColumnCFT.direction = getXmlAttributeValueBool(SecColumnCFTs[i], "direction");
                SecColumnCFT.base_type = getXmlAttributeValueString(SecColumnCFTs[i], "base_type");
                SecColumnCFT.enbedded_length = getXmlAttributeValueInt(SecColumnCFTs[i], "enbedded_length");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecColumnCFTs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    bool flag2 = false;
                    switch (SecColumnCFTs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelColumn_CFT": flag1 = true; break;
                        case "StbSecBaseProduct": flag2 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecColumnCFTs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELCOLUMN_CFT": flag1 = true; break;
                            case "STBSECBASEPRODUCT": flag2 = true; break;
                        }
                    }
                    if (flag1) SecColumnCFT.StbSecSteelColumn_CFT = new StbModelClass.StbSectionsClass.StbSecColumn_CFT.StbSecSteelColumn_CFT_Class[3];
                    if (flag2) SecColumnCFT.StbSecBaseProduct = new StbModelClass.StbSectionsClass.StbSecColumn_CFT.StbSecBaseProductClass();
                }
                // (値セット)
                for (int j = 0; j < SecColumnCFTs[i].ChildNodes.Count; j++)
                {
                    XmlNode Node = null;

                    bool flag1 = false;
                    bool flag2 = false;
                    switch (SecColumnCFTs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelColumn_CFT": flag1 = true; break;
                        case "StbSecBaseProduct": flag2 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecColumnCFTs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELCOLUMN_CFT": flag1 = true; break;
                            case "STBSECBASEPRODUCT": flag2 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- CFT柱鉄骨 ---
                        Node = SecColumnCFTs[i].ChildNodes[j];
                        string pos = getXmlAttributeValueString(Node, "pos");
                        int TBs = 0, TBe = 2;
                        if (pos == "ALL") { TBs = 0; TBe = 2; }
                        if (pos == "BOTTOM") { TBs = 0; TBe = 0; }
                        if (pos == "CENTER") { TBs = 1; TBe = 1; }
                        if (pos == "TOP") { TBs = 2; TBe = 2; }
                        if (!readUpLow)
                        {
                            // 大文字小文字を区別なく読み取る
                            if (pos.ToUpper() == "ALL") { TBs = 0; TBe = 2; }
                            if (pos.ToUpper() == "BOTTOM") { TBs = 0; TBe = 0; }
                            if (pos.ToUpper() == "CENTER") { TBs = 1; TBe = 1; }
                            if (pos.ToUpper() == "TOP") { TBs = 2; TBe = 2; }
                        }
                        for (int TB = TBs; TB <= TBe; TB++)
                        {
                            SecColumnCFT.StbSecSteelColumn_CFT[TB] = new StbModelClass.StbSectionsClass.StbSecColumn_CFT.StbSecSteelColumn_CFT_Class();
                            SecColumnCFT.StbSecSteelColumn_CFT[TB].pos = pos;
                            SecColumnCFT.StbSecSteelColumn_CFT[TB].shape = getXmlAttributeValueString(Node, "shape");
                            SecColumnCFT.StbSecSteelColumn_CFT[TB].strength_main = getXmlAttributeValueString(Node, "strength_main");
                        }
                    }
                    if (flag2)
                    {
                        //--- 柱脚製品 ---
                        Node = SecColumnCFTs[i].ChildNodes[j];
                        SecColumnCFT.StbSecBaseProduct.product_company = getXmlAttributeValueString(Node, "product_company");
                        SecColumnCFT.StbSecBaseProduct.product_code = getXmlAttributeValueString(Node, "product_code");
                    }
                }
                StbModel.StbSections.StbSecColumns_CFT.Add(SecColumnCFT);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < SecColumnCFTs.Count; i++)
            {
                //属性
                for (int j = 0; j < SecColumnCFTs[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "name", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "floor", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "kind_column", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "strength_concrete", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "direction", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "base_type", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].Attributes[j].Name, "enbedded_length", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnCFTs[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < SecColumnCFTs[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Name, "StbSecSteelColumn_CFT", true) == 0) diff = false;
                    if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Name, "StbSecBaseProduct", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecColumnCFTs[i].ChildNodes[k].Name + "]");
                    if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Name, "StbSecSteelColumn_CFT", true) == 0)
                    {
                        //子要素－属性
                        for (int j = 0; j < SecColumnCFTs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name, "pos", true) == 0) diff = false;
                            if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name, "shape", true) == 0) diff = false;
                            if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name, "strength_main", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                    if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Name, "StbSecBaseProduct", true) == 0)
                    {
                        for (int j = 0; j < SecColumnCFTs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name, "product_company", true) == 0) diff = false;
                            if (string.Compare(SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name, "product_code", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecColumnCFTs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
    private void ReadFile_StbSecBeam_RC(XmlDocument xml)
    {
        //
        // RC梁断面情報の読み取り
        //
        element = "RC梁断面(StbSecBeam_RC)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecBeamRCs = getXmlNodeList(xml, "StbSecBeam_RC");


        // RC梁断面
        if (SecBeamRCs.Count > 0)
