                SecBeamRC.strength_reinforcement_main = getXmlAttributeValueString(SecBeamRCs[i], "strength_reinforcement_main");
                SecBeamRC.strength_reinforcement_2nd_main = getXmlAttributeValueString(SecBeamRCs[i], "strength_reinforcement_2nd_main");
                SecBeamRC.strength_stirrup = getXmlAttributeValueString(SecBeamRCs[i], "strength_stirrup");
