                SecBeamRC.center_reinforcement_top = getXmlAttributeValueDouble(SecBeamRCs[i], "center_reinforcement_top");
                SecBeamRC.center_reinforcement_bottom = getXmlAttributeValueDouble(SecBeamRCs[i], "center_reinforcement_bottom");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecBeamRCs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    bool flag2 = false;
