                                SecBeamRC.StbSecFigure.StbSecHaunch = new StbModelClass.StbSectionsClass.StbSecBeam_RC.StbSecFigureClass.StbSecHaunchClass();
                                SecBeamRC.StbSecFigure.StbSecHaunch.width_start = getXmlAttributeValueDouble(Nodes[k], "width_start");
                                SecBeamRC.StbSecFigure.StbSecHaunch.depth_start = getXmlAttributeValueDouble(Nodes[k], "depth_start");
                                SecBeamRC.StbSecFigure.StbSecHaunch.width_center = getXmlAttributeValueDouble(Nodes[k], "width_center");
