                                SecBeamRC.StbSecFigure.StbSecHaunch.width_end = getXmlAttributeValueDouble(Nodes[k], "width_end");
                                SecBeamRC.StbSecFigure.StbSecHaunch.depth_end = getXmlAttributeValueDouble(Nodes[k], "depth_end");
