                                case "StbSecBeam_Same_Section": flag1 = true; break;
                                case "StbSecBeam_Start_Center_End_Section": flag2 = true; break;
                                case "StbSecBeam_Start_End_Section": flag3 = true; break;
                                case "StbSecBeam_XReinforced": flag4 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECBEAM_SAME_SECTION": flag1 = true; break;
                                    case "STBSECBEAM_START_CENTER_END_SECTION": flag2 = true; break;
