                                SecBeamRC.StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section[SCE].count_main_bottom_2nd = getXmlAttributeValueInt(Nodes[k], "count_main_bottom_2nd");
                                SecBeamRC.StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section[SCE].count_main_bottom_3rd = getXmlAttributeValueInt(Nodes[k], "count_main_bottom_3rd");
                                SecBeamRC.StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section[SCE].count_2nd_main_top_1st = getXmlAttributeValueInt(Nodes[k], "count_2nd_main_top_1st");
                                SecBeamRC.StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section[SCE].count_2nd_main_top_2nd = getXmlAttributeValueInt(Nodes[k], "count_2nd_main_top_2nd");
