    private void ReadFile_StbSecBeam_S(XmlDocument xml)
    {
        //
        // S梁断面情報の読み取り
        //
        element = "S梁断面(StbSecBeam_S)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecBeamSs = getXmlNodeList(xml, "StbSecBeam_S");


        // S梁断面
        if (SecBeamSs.Count > 0)
        {
            if (StbModel.StbSections.StbSecBeams_S == null) StbModel.StbSections.StbSecBeams_S = new List<StbModelClass.StbSectionsClass.StbSecBeam_S>();
            for (int i = 0; i < SecBeamSs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecBeamSs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecBeam_S SecBeamS = new StbModelClass.StbSectionsClass.StbSecBeam_S();
                SecBeamS.id = getXmlAttributeValueInt(SecBeamSs[i], "id");
                SecBeamS.name = getXmlAttributeValueString(SecBeamSs[i], "name");
                SecBeamS.floor = getXmlAttributeValueString(SecBeamSs[i], "floor");
                SecBeamS.kind_beam = getXmlAttributeValueString(SecBeamSs[i], "kind_beam");
                SecBeamS.isCanti = getXmlAttributeValueBool(SecBeamSs[i], "isCanti");
                SecBeamS.isOutIn = getXmlAttributeValueBool(SecBeamSs[i], "isOutIn");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecBeamSs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    switch (SecBeamSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelBeam": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecBeamSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELBEAM": flag1 = true; break;
                        }
                    }
                    if (flag1) SecBeamS.StbSecSteelBeam = new StbModelClass.StbSectionsClass.StbSecBeam_S.StbSecSteelBeamClass[5];
                }
                // (値セット)
                for (int j = 0; j < SecBeamSs[i].ChildNodes.Count; j++)
                {
                    XmlNode Node = null;
                    bool flag1 = false;
                    switch (SecBeamSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelBeam": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecBeamSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELBEAM": flag1 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- 梁鉄骨 ---
                        Node = SecBeamSs[i].ChildNodes[j];
                        string pos = getXmlAttributeValueString(Node, "pos");
                        int SEs = 0, SEe = 4;
                        if (pos == "ALL") { SEs = 0; SEe = 4; }
                        if (pos == "START") { SEs = 0; SEe = 0; }
                        if (pos == "CENTER") { SEs = 1; SEe = 1; }
                        if (pos == "END") { SEs = 2; SEe = 2; }
                        if (pos == "HAUNCH_S") { SEs = 3; SEe = 3; }
                        if (pos == "HAUNCH_E") { SEs = 4; SEe = 4; }
                        if (!readUpLow)
                        {
                            // 大文字小文字を区別なく読み取る
                            if (pos.ToUpper() == "ALL") { SEs = 0; SEe = 4; }
                            if (pos.ToUpper() == "START") { SEs = 0; SEe = 0; }
                            if (pos.ToUpper() == "CENTER") { SEs = 1; SEe = 1; }
                            if (pos.ToUpper() == "END") { SEs = 2; SEe = 2; }
                            if (pos.ToUpper() == "HAUNCH_S") { SEs = 3; SEe = 3; }
                            if (pos.ToUpper() == "HAUNCH_E") { SEs = 4; SEe = 4; }
                        }
                        for (int SE = SEs; SE <= SEe; SE++)
                        {
                            SecBeamS.StbSecSteelBeam[SE] = new StbModelClass.StbSectionsClass.StbSecBeam_S.StbSecSteelBeamClass();
                            SecBeamS.StbSecSteelBeam[SE].pos = pos;
                            SecBeamS.StbSecSteelBeam[SE].shape = getXmlAttributeValueString(Node, "shape");
                            SecBeamS.StbSecSteelBeam[SE].strength_main = getXmlAttributeValueString(Node, "strength_main");
                            SecBeamS.StbSecSteelBeam[SE].strength_web = getXmlAttributeValueString(Node, "strength_web");
                        }
                    }
                }
                StbModel.StbSections.StbSecBeams_S.Add(SecBeamS);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < SecBeamSs.Count; i++)
            {
                //属性
                for (int j = 0; j < SecBeamSs[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "name", true) == 0) diff = false;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "floor", true) == 0) diff = false;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "kind_beam", true) == 0) diff = false;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "isCanti", true) == 0) diff = false;
                    if (string.Compare(SecBeamSs[i].Attributes[j].Name, "isOutIn", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecBeamSs[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < SecBeamSs[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(SecBeamSs[i].ChildNodes[k].Name, "StbSecSteelBeam", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecBeamSs[i].ChildNodes[k].Name + "]");
                    //子要素－属性
                    if (string.Compare(SecBeamSs[i].ChildNodes[k].Name, "StbSecSteelBeam", true) == 0)
                    {
                        for (int j = 0; j < SecBeamSs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecBeamSs[i].ChildNodes[k].Attributes[j].Name, "pos", true) == 0) diff = false;
                            if (string.Compare(SecBeamSs[i].ChildNodes[k].Attributes[j].Name, "shape", true) == 0) diff = false;
                            if (string.Compare(SecBeamSs[i].ChildNodes[k].Attributes[j].Name, "strength_main", true) == 0) diff = false;
                            if (string.Compare(SecBeamSs[i].ChildNodes[k].Attributes[j].Name, "strength_web", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecBeamSs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
