    private void ReadFile_StbSecBrace_S(XmlDocument xml)
    {
        //
        // ブレース断面情報の読み取り
        //
        element = "Sブレース断面(StbSecBrace_S)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecBraceSs = getXmlNodeList(xml, "StbSecBrace_S");


        // ブレース断面
        if (SecBraceSs.Count > 0)
        {
            if (StbModel.StbSections.StbSecBraces_S == null) StbModel.StbSections.StbSecBraces_S = new List<StbModelClass.StbSectionsClass.StbSecBrace_S>();
            for (int i = 0; i < SecBraceSs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecBraceSs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecBrace_S SecBraceS = new StbModelClass.StbSectionsClass.StbSecBrace_S();
                SecBraceS.id = getXmlAttributeValueInt(SecBraceSs[i], "id");
                SecBraceS.name = getXmlAttributeValueString(SecBraceSs[i], "name");
                SecBraceS.floor = getXmlAttributeValueString(SecBraceSs[i], "floor");
                SecBraceS.kind_brace = getXmlAttributeValueString(SecBraceSs[i], "kind_brace");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecBraceSs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = true;
                    switch (SecBraceSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelBrace": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecBraceSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELBRACE": flag1 = true; break;
                        }
                    }
                    if (flag1) SecBraceS.StbSecSteelBrace = new StbModelClass.StbSectionsClass.StbSecBrace_S.StbSecSteelBraceClass[3];
                }
                // (値セット)
                for (int j = 0; j < SecBraceSs[i].ChildNodes.Count; j++)
                {
                    XmlNode Node = null;

                    bool flag1 = true;
                    switch (SecBraceSs[i].ChildNodes[j].Name)
                    {
                        case "StbSecSteelBrace": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecBraceSs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECSTEELBRACE": flag1 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- ブレース鉄骨 ---
                        Node = SecBraceSs[i].ChildNodes[j];
                        string pos = getXmlAttributeValueString(Node, "pos");
                        int SEs = 0, SEe = 2;
                        if (pos == "ALL") { SEs = 0; SEe = 2; }
                        if (pos == "BOTTOM") { SEs = 0; SEe = 0; }
                        if (pos == "CENTER") { SEs = 1; SEe = 1; }
                        if (pos == "TOP") { SEs = 2; SEe = 2; }
                        if (!readUpLow)
                        {
                            // 大文字小文字を区別なく読み取る
                            if (pos.ToUpper() == "ALL") { SEs = 0; SEe = 2; }
                            if (pos.ToUpper() == "BOTTOM") { SEs = 0; SEe = 0; }
                            if (pos.ToUpper() == "CENTER") { SEs = 1; SEe = 1; }
                            if (pos.ToUpper() == "TOP") { SEs = 2; SEe = 2; }
                        }
                        for (int SE = SEs; SE <= SEe; SE++)
                        {
                            SecBraceS.StbSecSteelBrace[SE] = new StbModelClass.StbSectionsClass.StbSecBrace_S.StbSecSteelBraceClass();
                            SecBraceS.StbSecSteelBrace[SE].pos = pos;
                            SecBraceS.StbSecSteelBrace[SE].shape = getXmlAttributeValueString(Node, "shape");
                            SecBraceS.StbSecSteelBrace[SE].strength_main = getXmlAttributeValueString(Node, "strength_main");
                            SecBraceS.StbSecSteelBrace[SE].strength_web = getXmlAttributeValueString(Node, "strength_web");
                        }
                    }
                }
                StbModel.StbSections.StbSecBraces_S.Add(SecBraceS);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < SecBraceSs.Count; i++)
            {
                //属性
                for (int j = 0; j < SecBraceSs[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(SecBraceSs[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(SecBraceSs[i].Attributes[j].Name, "name", true) == 0) diff = false;
                    if (string.Compare(SecBraceSs[i].Attributes[j].Name, "floor", true) == 0) diff = false;
                    if (string.Compare(SecBraceSs[i].Attributes[j].Name, "kind_brace", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecBraceSs[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < SecBraceSs[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(SecBraceSs[i].ChildNodes[k].Name, "StbSecSteelBrace", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecBraceSs[i].ChildNodes[k].Name + "]");
                    //子要素－属性
                    if (string.Compare(SecBraceSs[i].ChildNodes[k].Name, "StbSecSteelBrace", true) == 0)
                    {
                        for (int j = 0; j < SecBraceSs[i].ChildNodes[k].Attributes.Count; j++)
                        {
                            diff = true;
                            if (string.Compare(SecBraceSs[i].ChildNodes[k].Attributes[j].Name, "pos", true) == 0) diff = false;
                            if (string.Compare(SecBraceSs[i].ChildNodes[k].Attributes[j].Name, "shape", true) == 0) diff = false;
                            if (string.Compare(SecBraceSs[i].ChildNodes[k].Attributes[j].Name, "strength_main", true) == 0) diff = false;
                            if (string.Compare(SecBraceSs[i].ChildNodes[k].Attributes[j].Name, "strength_web", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecBraceSs[i].ChildNodes[k].Attributes[j].Name + "]");
                        }
                    }
                }
            }

            GaugePercent(element + " 読み込み", 100);
        }
    }
