    private void ReadFile_StbSecSlab_Deck(XmlDocument xml)
    {
        //
        // デッキプレートスラブ断面情報の読み取り
        //
        element = "デッキプレートスラブ断面(StbSecSlab_Deck)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecSlabDecks = getXmlNodeList(xml, "StbSecSlab_Deck");


        // デッキスラブ断面
        if (SecSlabDecks.Count > 0)
        {
            if (StbModel.StbSections.StbSecSlabs_Deck == null) StbModel.StbSections.StbSecSlabs_Deck = new List<StbModelClass.StbSectionsClass.StbSecSlab_Deck>();
            for (int i = 0; i < SecSlabDecks.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecSlabDecks.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecSlab_Deck SecSlabDeck = new StbModelClass.StbSectionsClass.StbSecSlab_Deck();
                SecSlabDeck.id = getXmlAttributeValueInt(SecSlabDecks[i], "id");
                SecSlabDeck.name = getXmlAttributeValueString(SecSlabDecks[i], "name");
                SecSlabDeck.product_type = getXmlAttributeValueString(SecSlabDecks[i], "product_type");
                SecSlabDeck.strength_concrete = getXmlAttributeValueString(SecSlabDecks[i], "strength_concrete");
                SecSlabDeck.depth_concrete = getXmlAttributeValueDouble(SecSlabDecks[i], "depth_concrete");
                SecSlabDeck.depth_cover_top = getXmlAttributeValueDouble(SecSlabDecks[i], "depth_cover_top");
                SecSlabDeck.depth_cover_bottom = getXmlAttributeValueDouble(SecSlabDecks[i], "depth_cover_bottom");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecSlabDecks[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    bool flag2 = false;
                    switch (SecSlabDecks[i].ChildNodes[j].Name)
                    {
                        case "StbSecBar_Arrangement": flag1 = true; break;
                        case "StbSecDeck_Product": flag2 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecSlabDecks[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECBAR_ARRANGEMENT": flag1 = true; break;
                            case "STBSECDECK_PRODUCT": flag2 = true; break;
                        }
                    }
                    if (flag1) SecSlabDeck.StbSecBar_Arrangement = new StbModelClass.StbSectionsClass.StbSecSlab_Deck.StbSecBar_ArrangementClass();
                    if (flag2) SecSlabDeck.StbSecDeck_Product = new StbModelClass.StbSectionsClass.StbSecSlab_Deck.StbSecDeck_ProductClass();
                }
                // (値セット)
                for (int j = 0; j < SecSlabDecks[i].ChildNodes.Count; j++)
                {
                    XmlNodeList Nodes = null;
                    XmlNode Node = null;

                    bool flag1 = false;
                    bool flag2 = false;
                    bool flag3 = false;
