    private void ReadFile_StbSecWall_RC(XmlDocument xml)
    {
        //
        // RC壁断面情報の読み取り
        //
        element = "RC壁断面(StbSecWall_RC)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecWallRCs = getXmlNodeList(xml, "StbSecWall_RC");


        // 壁断面
        if (SecWallRCs.Count > 0)
        {
            if (StbModel.StbSections.StbSecWalls_RC == null) StbModel.StbSections.StbSecWalls_RC = new List<StbModelClass.StbSectionsClass.StbSecWall_RC>();
            for (int i = 0; i < SecWallRCs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecWallRCs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecWall_RC SecWallRC = new StbModelClass.StbSectionsClass.StbSecWall_RC();
                SecWallRC.id = getXmlAttributeValueInt(SecWallRCs[i], "id");
                SecWallRC.name = getXmlAttributeValueString(SecWallRCs[i], "name");
                SecWallRC.depth = getXmlAttributeValueDouble(SecWallRCs[i], "depth");
                SecWallRC.strength_concrete = getXmlAttributeValueString(SecWallRCs[i], "strength_concrete");
                SecWallRC.depth_cover_outside = getXmlAttributeValueDouble(SecWallRCs[i], "depth_cover_outside");
                SecWallRC.depth_cover_inside = getXmlAttributeValueDouble(SecWallRCs[i], "depth_cover_inside");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecWallRCs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    switch (SecWallRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecBar_Arrangement": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecWallRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECBAR_ARRANGEMENT": flag1 = true; break;
                        }
                    }
                    if (flag1) SecWallRC.StbSecBar_Arrangement = new StbModelClass.StbSectionsClass.StbSecWall_RC.StbSecBar_ArrangementClass();
                }
                // (値セット)
                for (int j = 0; j < SecWallRCs[i].ChildNodes.Count; j++)
