                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecWallRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECBAR_ARRANGEMENT": flag1 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- 配筋 ---
                        Nodes = SecWallRCs[i].ChildNodes[j].ChildNodes;
