    private void ReadFile_StbSecPile_RC(XmlDocument xml)
    {
        //
        // RC杭断面情報の読み取り
        //
        element = "RC杭断面(StbSecPile_RC)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecPileRCs = getXmlNodeList(xml, "StbSecPile_RC");


        // 杭断面
        if (SecPileRCs.Count > 0)
        {
            if (StbModel.StbSections.StbSecPiles_RC == null) StbModel.StbSections.StbSecPiles_RC = new List<StbModelClass.StbSectionsClass.StbSecPile_RC>();
            for (int i = 0; i < SecPileRCs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecPileRCs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecPile_RC SecPileRC = new StbModelClass.StbSectionsClass.StbSecPile_RC();
                SecPileRC.id = getXmlAttributeValueInt(SecPileRCs[i], "id");
                SecPileRC.name = getXmlAttributeValueString(SecPileRCs[i], "name");
                SecPileRC.strength_concrete = getXmlAttributeValueString(SecPileRCs[i], "strength_concrete");
                SecPileRC.depth_cover = getXmlAttributeValueDouble(SecPileRCs[i], "depth_cover");
                SecPileRC.depth_cover_top = getXmlAttributeValueDouble(SecPileRCs[i], "depth_cover_top");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecPileRCs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    bool flag2 = false;
                    switch (SecPileRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecFigure": flag1 = true; break;
                        case "StbSecBar_Arrangement": flag2 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecPileRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECFIGURE": flag1 = true; break;
                            case "STBSECBAR_ARRANGEMENT": flag2 = true; break;
                        }
                    }
                    if (flag1) SecPileRC.StbSecFigure = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecFigureClass();
                    if (flag2) SecPileRC.StbSecBar_Arrangement = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass();
                }
                // (値セット)
                for (int j = 0; j < SecPileRCs[i].ChildNodes.Count; j++)
                {
                    XmlNodeList Nodes = null;
                    bool flag1 = false;
                    bool flag2 = false;
                    bool flag3 = false;
                    bool flag4 = false;
                    switch (SecPileRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecFigure": flag1 = true; break;
                        case "StbSecBar_Arrangement": flag2 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecPileRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECFIGURE": flag1 = true; break;
                            case "STBSECBAR_ARRANGEMENT": flag2 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- 形状 ---
                        Nodes = SecPileRCs[i].ChildNodes[j].ChildNodes;
                        for (int k = 0; k < Nodes.Count; k++)
                        {
                            flag1 = false;
                            flag2 = false;
                            flag3 = false;
                            flag4 = false;
                            switch (Nodes[k].Name)
                            {
                                case "StbSecStraight": flag1 = true; break;
                                case "StbSecExtended_Foot": flag2 = true; break;
                                case "StbSecExtended_Top": flag3 = true; break;
                                case "StbSecExtended_Top_Foot": flag4 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECSTRAIGHT": flag1 = true; break;
                                    case "STBSECEXTENDED_FOOT": flag2 = true; break;
                                    case "STBSECEXTENDED_TOP": flag3 = true; break;
                                    case "STBSECEXTENDED_TOP_FOOT": flag4 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                SecPileRC.StbSecFigure.StbSecFigureType = 1;
                                SecPileRC.StbSecFigure.StbSecStraight = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecFigureClass.StbSecStraight_Class();
                                SecPileRC.StbSecFigure.StbSecStraight.D = getXmlAttributeValueDouble(Nodes[k], "D");
                            }
                            if (flag2)
                            {
                                SecPileRC.StbSecFigure.StbSecFigureType = 2;
                                SecPileRC.StbSecFigure.StbSecExtended_Foot = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecFigureClass.StbSecExtended_Foot_Class();
                                SecPileRC.StbSecFigure.StbSecExtended_Foot.D_axial = getXmlAttributeValueDouble(Nodes[k], "D_axial");
                                SecPileRC.StbSecFigure.StbSecExtended_Foot.D_extended_foot = getXmlAttributeValueDouble(Nodes[k], "D_extended_foot");
                            }
                            if (flag3)
                            {
                                SecPileRC.StbSecFigure.StbSecFigureType = 3;
                                SecPileRC.StbSecFigure.StbSecExtended_Top = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecFigureClass.StbSecExtended_Top_Class();
                                SecPileRC.StbSecFigure.StbSecExtended_Top.D_extended_top = getXmlAttributeValueDouble(Nodes[k], "D_extended_top");
                                SecPileRC.StbSecFigure.StbSecExtended_Top.D_axial = getXmlAttributeValueDouble(Nodes[k], "D_axial");
                            }
                            if (flag4)
                            {
                                SecPileRC.StbSecFigure.StbSecFigureType = 4;
                                SecPileRC.StbSecFigure.StbSecExtended_Top_Foot = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecFigureClass.StbSecExtended_Top_Foot_Class();
                                SecPileRC.StbSecFigure.StbSecExtended_Top_Foot.D_extended_top = getXmlAttributeValueDouble(Nodes[k], "D_extended_top");
                                SecPileRC.StbSecFigure.StbSecExtended_Top_Foot.D_axial = getXmlAttributeValueDouble(Nodes[k], "D_axial");
                                SecPileRC.StbSecFigure.StbSecExtended_Top_Foot.D_extended_foot = getXmlAttributeValueDouble(Nodes[k], "D_extended_foot");
                            }
                        }
                    }
                    if (flag2)
                    {
                        //--- 配筋 ---
                        Nodes = SecPileRCs[i].ChildNodes[j].ChildNodes;
                        //(変数初期化)
                        for (int k = 0; k < Nodes.Count; k++)
                        {
                            flag1 = false;
                            flag2 = false;
                            flag3 = false;
                            switch (Nodes[k].Name)
                            {
                                case "StbSecPile_Same": flag1 = true; break;
                                case "StbSecPile_Top_Bottom": flag2 = true; break;
                                case "StbSecPile_Top_Center_Bottom": flag3 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECPILE_SAME": flag1 = true; break;
                                    case "STBSECPILE_TOP_BOTTOM": flag2 = true; break;
                                    case "STBSECPILE_TOP_CENTER_BOTTOM": flag3 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                SecPileRC.StbSecBar_Arrangement.StbSecBar_ArrangementType = 1;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Same_Class();
                            }
                            if (flag2)
                            {
                                SecPileRC.StbSecBar_Arrangement.StbSecBar_ArrangementType = 2;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Top_Bottom_Class[2];
                            }
                            if (flag3)
                            {
                                SecPileRC.StbSecBar_Arrangement.StbSecBar_ArrangementType = 3;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Top_Center_Bottom_Class[3];
                            }
                        }
                        //(値セット)
                        for (int k = 0; k < Nodes.Count; k++)
                        {
                            string pos = "";
                            int ind = 0;
                            pos = getXmlAttributeValueString(Nodes[k], "pos").ToUpper();
                            flag1 = false;
                            flag2 = false;
                            flag3 = false;
                            switch (Nodes[k].Name)
                            {
                                case "StbSecPile_Same": flag1 = true; break;
                                case "StbSecPile_Top_Bottom": flag2 = true; break;
                                case "StbSecPile_Top_Center_Bottom": flag3 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECPILE_SAME": flag1 = true; break;
                                    case "STBSECPILE_TOP_BOTTOM": flag2 = true; break;
                                    case "STBSECPILE_TOP_CENTER_BOTTOM": flag3 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Same_Class();
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.strength_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "strength_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.D_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "D_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.count_main_circumference_1st = getXmlAttributeValueInt(Nodes[k], "count_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.strength_main_core = getXmlAttributeValueString(Nodes[k], "strength_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.D_main_core = getXmlAttributeValueString(Nodes[k], "D_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.count_main_core = getXmlAttributeValueInt(Nodes[k], "count_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.strength_band = getXmlAttributeValueString(Nodes[k], "strength_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.D_band = getXmlAttributeValueString(Nodes[k], "D_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Same.pitch_band = getXmlAttributeValueDouble(Nodes[k], "pitch_band");
                            }
                            if (flag2)
                            {
                                if (pos == "TOP") ind = 0;
                                if (pos == "BOTTOM") ind = 1;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind] = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Top_Bottom_Class();
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].pos = pos;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].strength_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "strength_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].D_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "D_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].count_main_circumference_1st = getXmlAttributeValueInt(Nodes[k], "count_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].strength_main_core = getXmlAttributeValueString(Nodes[k], "strength_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].D_main_core = getXmlAttributeValueString(Nodes[k], "D_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].count_main_core = getXmlAttributeValueInt(Nodes[k], "count_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].strength_band = getXmlAttributeValueString(Nodes[k], "strength_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].D_band = getXmlAttributeValueString(Nodes[k], "D_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Bottom[ind].pitch_band = getXmlAttributeValueDouble(Nodes[k], "pitch_band");
                            }
                            if (flag3)
                            {
                                if (pos == "TOP") ind = 0;
                                if (pos == "CENTER") ind = 1;
                                if (pos == "BOTTOM") ind = 2;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind] = new StbModelClass.StbSectionsClass.StbSecPile_RC.StbSecBar_ArrangementClass.StbSecPile_Top_Center_Bottom_Class();
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].pos = pos;
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].strength_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "strength_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].D_main_circumference_1st = getXmlAttributeValueString(Nodes[k], "D_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].count_main_circumference_1st = getXmlAttributeValueInt(Nodes[k], "count_main_circumference_1st");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].strength_main_core = getXmlAttributeValueString(Nodes[k], "strength_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].D_main_core = getXmlAttributeValueString(Nodes[k], "D_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].count_main_core = getXmlAttributeValueInt(Nodes[k], "count_main_core");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].strength_band = getXmlAttributeValueString(Nodes[k], "strength_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].D_band = getXmlAttributeValueString(Nodes[k], "D_band");
                                SecPileRC.StbSecBar_Arrangement.StbSecPile_Top_Center_Bottom[ind].pitch_band = getXmlAttributeValueDouble(Nodes[k], "pitch_band");
                            }
                        }
                    }
                }
                StbModel.StbSections.StbSecPiles_RC.Add(SecPileRC);
