    private void ReadFile_StbSecOpen_RC(XmlDocument xml)
    {
        //
        // RC開口断面情報の読み取り
        //
        element = "RC開口断面(StbSecOpen_RC)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecOpenRCs = getXmlNodeList(xml, "StbSecOpen_RC");


        // 開口断面
        if (SecOpenRCs.Count > 0)
        {
            if (StbModel.StbSections.StbSecOpens_RC == null) StbModel.StbSections.StbSecOpens_RC = new List<StbModelClass.StbSectionsClass.StbSecOpen_RC>();
            for (int i = 0; i < SecOpenRCs.Count; i++)
            {
                GaugePercent(element + " 読み込み", (int)((double)(i + 1) / (double)(SecOpenRCs.Count) * 100));
                StbModelClass.StbSectionsClass.StbSecOpen_RC SecOpenRC = new StbModelClass.StbSectionsClass.StbSecOpen_RC();
                SecOpenRC.id = getXmlAttributeValueInt(SecOpenRCs[i], "id");
                SecOpenRC.name = getXmlAttributeValueString(SecOpenRCs[i], "name");

                //(子要素)
                // (初期化)
                for (int j = 0; j < SecOpenRCs[i].ChildNodes.Count; j++)
                {
                    bool flag1 = false;
                    switch (SecOpenRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecBar_Arrangement": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecOpenRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECBAR_ARRANGEMENT": flag1 = true; break;
                        }
                    }
                    if (flag1) SecOpenRC.StbSecBar_Arrangement = new StbModelClass.StbSectionsClass.StbSecOpen_RC.StbSecBar_ArrangementClass();
                }
                // (値セット)
                for (int j = 0; j < SecOpenRCs[i].ChildNodes.Count; j++)
                {
                    XmlNodeList Nodes = null;
                    bool flag1 = false;
                    bool flag2 = false;
                    switch (SecOpenRCs[i].ChildNodes[j].Name)
                    {
                        case "StbSecBar_Arrangement": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecOpenRCs[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECBAR_ARRANGEMENT": flag1 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        //--- 配筋 ---
                        Nodes = SecOpenRCs[i].ChildNodes[j].ChildNodes;
                        //(変数初期化)
                        for (int k = 0; k < Nodes.Count; k++)
                        {
                            flag1 = false;
                            flag2 = false;
                            switch (Nodes[k].Name)
                            {
                                case "StbSecOpen_Slab": flag1 = true; break;
                                case "StbSecOpen_Wall": flag2 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECOPEN_SLAB": flag1 = true; break;
                                    case "STBSECOPEN_WALL": flag2 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                SecOpenRC.StbSecBar_Arrangement.StbSecBar_ArrangementType = 1;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab = new StbModelClass.StbSectionsClass.StbSecOpen_RC.StbSecBar_ArrangementClass.StbSecOpen_Slab_Class[6];
                            }
                            if (flag2)
                            {
                                SecOpenRC.StbSecBar_Arrangement.StbSecBar_ArrangementType = 2;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall = new StbModelClass.StbSectionsClass.StbSecOpen_RC.StbSecBar_ArrangementClass.StbSecOpen_Wall_Class[3];
                            }
                        }
                        //(値セット)
                        for (int k = 0; k < Nodes.Count; k++)
                        {
                            string pos = "";
                            int ind = 0;
                            pos = getXmlAttributeValueString(Nodes[k], "pos").ToUpper();
                            flag1 = false;
                            flag2 = false;
                            switch (Nodes[k].Name)
                            {
                                case "StbSecOpen_Slab": flag1 = true; break;
                                case "StbSecOpen_Wall": flag2 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Nodes[k].Name.ToUpper())
                                {
                                    case "STBSECOPEN_SLAB": flag1 = true; break;
                                    case "STBSECOPEN_WALL": flag2 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                if (pos == "X_TOP") ind = 0;
                                if (pos == "X_BOTTOM") ind = 1;
                                if (pos == "Y_TOP") ind = 2;
                                if (pos == "Y_BOTTOM") ind = 3;
                                if (pos == "DIAGONAL_TOP") ind = 4;
                                if (pos == "DIAGONAL_BOTTOM") ind = 5;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind] = new StbModelClass.StbSectionsClass.StbSecOpen_RC.StbSecBar_ArrangementClass.StbSecOpen_Slab_Class();
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind].pos = pos;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind].strength = getXmlAttributeValueString(Nodes[k], "strength");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind].D = getXmlAttributeValueString(Nodes[k], "D");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind].count = getXmlAttributeValueInt(Nodes[k], "count");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Slab[ind].length = getXmlAttributeValueDouble(Nodes[k], "length");
                            }
                            if (flag2)
                            {
                                if (pos == "VERTICAL") ind = 0;
                                if (pos == "HORIZONTAL") ind = 1;
                                if (pos == "DIAGONAL") ind = 2;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind] = new StbModelClass.StbSectionsClass.StbSecOpen_RC.StbSecBar_ArrangementClass.StbSecOpen_Wall_Class();
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind].pos = pos;
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind].strength = getXmlAttributeValueString(Nodes[k], "strength");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind].D = getXmlAttributeValueString(Nodes[k], "D");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind].count = getXmlAttributeValueInt(Nodes[k], "count");
                                SecOpenRC.StbSecBar_Arrangement.StbSecOpen_Wall[ind].length = getXmlAttributeValueDouble(Nodes[k], "length");
                            }
                        }
                    }
                }
                StbModel.StbSections.StbSecOpens_RC.Add(SecOpenRC);
            }


            // 認識不可タグのチェック
            for (int i = 0; i < SecOpenRCs.Count; i++)
            {
                //属性
                for (int j = 0; j < SecOpenRCs[i].Attributes.Count; j++)
                {
                    bool diff = true;
                    if (string.Compare(SecOpenRCs[i].Attributes[j].Name, "id", true) == 0) diff = false;
                    if (string.Compare(SecOpenRCs[i].Attributes[j].Name, "name", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecOpenRCs[i].Attributes[j].Name + "]");
                }
                //子要素
                for (int k = 0; k < SecOpenRCs[i].ChildNodes.Count; k++)
                {
                    bool diff = true;
                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].Name, "StbSecBar_Arrangement", true) == 0) diff = false;
                    if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecOpenRCs[i].ChildNodes[k].Name + "]");
                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].Name, "StbSecBar_Arrangement", true) == 0)
                    {
                        //子子要素
                        for (int k2 = 0; k2 < SecOpenRCs[i].ChildNodes[k].ChildNodes.Count; k2++)
                        {
                            diff = true;
                            if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Name, "StbSecOpen_Slab", true) == 0) diff = false;
                            if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Name, "StbSecOpen_Wall", true) == 0) diff = false;
                            if (diff) unknownListAdd(element + "に認識できない子要素があります。[" + SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Name + "]");
                            //子子要素－属性
                            if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Name, "StbSecOpen_Slab", true) == 0)
                            {
                                for (int j = 0; j < SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes.Count; j++)
                                {
                                    diff = true;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "pos", true) == 0) diff = false;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "strength", true) == 0) diff = false;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "D", true) == 0) diff = false;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "count", true) == 0) diff = false;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "length", true) == 0) diff = false;
                                    if (diff) unknownListAdd(element + "に認識できない属性があります。[" + SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name + "]");
                                }
                            }
                            if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Name, "StbSecOpen_Wall", true) == 0)
                            {
                                for (int j = 0; j < SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes.Count; j++)
                                {
                                    diff = true;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "pos", true) == 0) diff = false;
                                    if (string.Compare(SecOpenRCs[i].ChildNodes[k].ChildNodes[k2].Attributes[j].Name, "strength", true) == 0) diff = false;
