    private void ReadFile_StbSecSteel(XmlDocument xml)
    {
        //
        // 鉄骨断面情報の読み取り
        //
        element = "鉄骨断面(StbSecSteel)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SecSteels = getXmlNodeList(xml, "StbSecSteel");


        int gaugeMax = 0;
        int gaugeNow = 0;
        for (int i = 0; i < SecSteels.Count; i++)
        { gaugeMax += SecSteels[i].ChildNodes.Count * 2; }


        // 鉄骨断面
        if (SecSteels.Count > 0)
        {
            if (StbModel.StbSections.StbSecSteel == null) StbModel.StbSections.StbSecSteel = new StbModelClass.StbSectionsClass.StbSecSteel_Class();
            for (int i = 0; i < SecSteels.Count; i++)
            {
                //(子要素)
                // (初期化)
                for (int j = 0; j < SecSteels[i].ChildNodes.Count; j++)
                {
                    gaugeNow += 1; GaugePercent(element + " 読み込み", (int)((double)gaugeNow / (double)gaugeMax * 100));
                    bool flag1 = false;
                    bool flag2 = false;
                    bool flag3 = false;
                    bool flag4 = false;
                    bool flag5 = false;
                    bool flag6 = false;
                    bool flag7 = false;
                    bool flag8 = false;
                    bool flag9 = false;
                    bool flag10 = false;
                    bool flag11 = false;
                    switch (SecSteels[i].ChildNodes[j].Name)
                    {
                        case "StbSecRoll-H": flag1 = true; break;
                        case "StbSecBuild-H": flag2 = true; break;
                        case "StbSecRoll-BOX": flag3 = true; break;
                        case "StbSecBuild-BOX": flag4 = true; break;
                        case "StbSecPipe": flag5 = true; break;
                        case "StbSecRoll-T": flag6 = true; break;
                        case "StbSecRoll-C": flag7 = true; break;
                        case "StbSecRoll-L": flag8 = true; break;
                        case "StbSecRoll-LipC": flag9 = true; break;
                        case "StbSecRoll-FB": flag10 = true; break;
                        case "StbSecRoll-Bar": flag11 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (SecSteels[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBSECROLL-H": flag1 = true; break;
                            case "STBSECBUILD-H": flag2 = true; break;
