    private void ReadFile_StbSlabFrames(XmlDocument xml)
    {
        // 床組を出力するアプリは無いため当面対象外
        bool flag1 = false;

        //
        // 床組情報の読み取り
        //
        element = "床組(StbSlabFrames)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList SlabFrameArranges = getXmlNodeList(xml, "StbSlabFrameArranges");
        XmlNodeList SlabFramePatterns = getXmlNodeList(xml, "StbSlabFramePatterns");


        int gaugeMax = 0;
        int gaugeNow = 0;
        for (int i = 0; i < SlabFrameArranges.Count; i++)
        { gaugeMax += SlabFrameArranges[i].ChildNodes.Count * 2; }
        for (int i = 0; i < SlabFramePatterns.Count; i++)
        { gaugeMax += SlabFramePatterns[i].ChildNodes.Count * 2; }


