            {
                //(子要素)
                // (初期化)
                for (int j = 0; j < SlabFrameArranges[i].ChildNodes.Count; j++)
                {
                    gaugeNow += 1; GaugePercent(element + " 読み込み", (int)((double)gaugeNow / (double)gaugeMax * 100));
                    flag1 = false;
                    switch (SlabFrameArranges[i].ChildNodes[j].Name)
                    {
                        case "StbSlabFrameArrange": flag1 = true; break;
