    private void ReadFile_StbExtensions(XmlDocument xml)
    {
        //
        // 拡張情報の読み取り
        //
        element = "拡張情報(StbExtensions)";
        GaugePercent(element + " 読み込み", 0);

        XmlNodeList Extensions = getXmlNodeList(xml, "StbExtension");


        int gaugeMax = 0;
        int gaugeNow = 0;
        for (int i = 0; i < Extensions.Count; i++)
        {
            for (int j = 0; j < Extensions[i].ChildNodes.Count; j++)
            { gaugeMax += Extensions[i].ChildNodes[j].ChildNodes.Count * 2; }
        }


        // 拡張情報
        bool flag1 = false;
        if (Extensions.Count > 0)
        {
            if (StbExtensions.StbExtension == null) StbExtensions.StbExtension = new List<StbExtensionsClass.StbExtensionClass>();
            for (int i = 0; i < Extensions.Count; i++)
            {
                StbExtensionsClass.StbExtensionClass ext = new StbExtensionsClass.StbExtensionClass();
                ext.identifier = getXmlAttributeValueString(Extensions[i], "identifier");
                ext.description = getXmlAttributeValueString(Extensions[i], "description");

                //(子要素)
                // (初期化)
                for (int j = 0; j < Extensions[i].ChildNodes.Count; j++)
                {
                    flag1 = false;
                    switch (Extensions[i].ChildNodes[j].Name)
                    {
                        case "StbExtObject": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (Extensions[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBEXTOBJECT": flag1 = true; break;
                        }
                    }
                    if (flag1) if (ext.StbExtObject == null) ext.StbExtObject = new List<StbExtensionsClass.StbExtensionClass.StbExtObjectClass>();
                }
                // (値セット)
                for (int j = 0; j < Extensions[i].ChildNodes.Count; j++)
                {
                    flag1 = false;
                    switch (Extensions[i].ChildNodes[j].Name)
                    {
                        case "StbExtObject": flag1 = true; break;
                    }
                    if (!readUpLow)
                    {
                        // 大文字小文字を区別なく読み取る
                        switch (Extensions[i].ChildNodes[j].Name.ToUpper())
                        {
                            case "STBEXTOBJECT": flag1 = true; break;
                        }
                    }
                    if (flag1)
                    {
                        // 対象オブジェクト

                        StbExtensionsClass.StbExtensionClass.StbExtObjectClass obj = new StbExtensionsClass.StbExtensionClass.StbExtObjectClass();
                        obj.objectName = getXmlAttributeValueString(Extensions[i].ChildNodes[j], "objectName");
                        obj.objectID = getXmlAttributeValueInt(Extensions[i].ChildNodes[j], "objectID");

                        //(子要素)
                        // (初期化)
                        for (int k = 0; k < Extensions[i].ChildNodes[j].ChildNodes.Count; k++)
                        {
                            gaugeNow += 1; GaugePercent(element + " 読み込み", (int)((double)gaugeNow / (double)gaugeMax * 100));
                            flag1 = false;
                            switch (Extensions[i].ChildNodes[j].ChildNodes[k].Name)
                            {
                                case "StbExtProperty": flag1 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Extensions[i].ChildNodes[j].ChildNodes[k].Name.ToUpper())
                                {
                                    case "STBEXTPROPERTY": flag1 = true; break;
                                }
                            }
                            if (flag1) if (obj.StbExtProperty == null) obj.StbExtProperty = new List<StbExtensionsClass.StbExtensionClass.StbExtObjectClass.StbExtPropertyClass>();
                        }
                        // (値セット)
                        for (int k = 0; k < Extensions[i].ChildNodes[j].ChildNodes.Count; k++)
                        {
                            gaugeNow += 1; GaugePercent(element + " 読み込み", (int)((double)gaugeNow / (double)gaugeMax * 100));
                            flag1 = false;
                            switch (Extensions[i].ChildNodes[j].ChildNodes[k].Name)
                            {
                                case "StbExtProperty": flag1 = true; break;
                            }
                            if (!readUpLow)
                            {
                                // 大文字小文字を区別なく読み取る
                                switch (Extensions[i].ChildNodes[j].ChildNodes[k].Name.ToUpper())
                                {
                                    case "STBEXTPROPERTY": flag1 = true; break;
                                }
                            }
                            if (flag1)
                            {
                                // 拡張属性
                                StbExtensionsClass.StbExtensionClass.StbExtObjectClass.StbExtPropertyClass ExtProperty = new StbExtensionsClass.StbExtensionClass.StbExtObjectClass.StbExtPropertyClass();
                                ExtProperty.key = getXmlAttributeValueString(Extensions[i].ChildNodes[j].ChildNodes[k], "key");
                                ExtProperty.type = getXmlAttributeValueString(Extensions[i].ChildNodes[j].ChildNodes[k], "type");
                                ExtProperty.value = getXmlAttributeValueString(Extensions[i].ChildNodes[j].ChildNodes[k], "value");
                                obj.StbExtProperty.Add(ExtProperty);
                            }
                        }

                        ext.StbExtObject.Add(obj);
                    }
                }
                StbExtensions.StbExtension.Add(ext);
            }
        }
    }

    /// <summary>認識不可リストへの登録
    /// </summary>
    private void unknownListAdd(string warning = "")
    {
        if (!unknownList.Contains(warning)) unknownList.Add(warning);
    }


