    //***** ファイルの書き込み *****//

    /// <summary>STBファイルの書き込み
    /// </summary>
    /// <param name="form">進捗状況を表示するForm(画面中央にゲージを表示)</param>
    /// <returns>エラーメッセージ</returns>
    internal string WriteFile(string stbFile, Form form = null, string encoding = "Shift_JIS")
    {
        string errmsg = "";
        Stopwatch sw = new Stopwatch();


        try
        {
            // 進捗ゲージの表示
            gaugeForm = null;
            if (form != null)
            {
                gaugeForm = form;
                sw.Start();
                GaugeShow();
            }


            if (File.Exists(stbFile)) File.Delete(stbFile);


            XmlDocument xml = new XmlDocument();
            element = "";


            // ■ XMLヘッダー
            XmlDeclaration declaration = xml.CreateXmlDeclaration(@"1.0", encoding, null); //@"UTF-8" //STBviewerが[UTF-8]に対応していないため[Shift_JIS]で出力
            xml.AppendChild(declaration);


            // ■ ST_BRIDGE
            element = "ST_BRIDGEタグ(バージョン)";
            XmlElement StBridge = xml.CreateElement("ST_BRIDGE");
            StBridge.SetAttribute("version", version);
            xml.AppendChild(StBridge);


            // ■ StbCommon
            WriteXmlElement_StbCommon(xml, StBridge);


            // ■ StbModel
            XmlElement model = xml.CreateElement("StbModel");
            WriteXmlElement_StbNodes(xml, model);
            WriteXmlElement_StbAxes(xml, model);
            WriteXmlElement_StbStories(xml, model);

            //  □ StbModel.StbMembers
            if (StbModel.StbMembers != null)
            {
                XmlElement Members = xml.CreateElement("StbMembers");
                WriteXmlElement_StbColumns(xml, Members);
                WriteXmlElement_StbPosts(xml, Members);
                WriteXmlElement_StbGirders(xml, Members);
                WriteXmlElement_StbBeams(xml, Members);
                WriteXmlElement_StbBraces(xml, Members);
                WriteXmlElement_StbSlabs(xml, Members);
                WriteXmlElement_StbWalls(xml, Members);
                WriteXmlElement_StbFootings(xml, Members);
                WriteXmlElement_StbStrip_Footings(xml, Members);
                WriteXmlElement_StbPiles(xml, Members);
                WriteXmlElement_StbFoundationColumns(xml, Members);
                WriteXmlElement_StbParapets(xml, Members);
                model.AppendChild(Members);
            }

            //  □ StbModel.StbSections
            if (StbModel.StbSections != null)
            {
                XmlElement Sections = xml.CreateElement("StbSections");
                WriteXmlElement_StbSecColumn_RC(xml, Sections);
                WriteXmlElement_StbSecColumn_S(xml, Sections);
                WriteXmlElement_StbSecColumn_SRC(xml, Sections);
                WriteXmlElement_StbSecColumn_CFT(xml, Sections);
                WriteXmlElement_StbSecBeam_RC(xml, Sections);
                WriteXmlElement_StbSecBeam_S(xml, Sections);
                WriteXmlElement_StbSecBeam_SRC(xml, Sections);
                WriteXmlElement_StbSecBrace_S(xml, Sections);
                WriteXmlElement_StbSecSlab_RC(xml, Sections);
                WriteXmlElement_StbSecSlab_Deck(xml, Sections);
                WriteXmlElement_StbSecWall_RC(xml, Sections);
                WriteXmlElement_StbSecFoundation_RC(xml, Sections);
                WriteXmlElement_StbSecPile_RC(xml, Sections);
                WriteXmlElement_StbSecOpen_RC(xml, Sections);
                WriteXmlElement_StbSecParapet_RC(xml, Sections);
                WriteXmlElement_StbSecSteel(xml, Sections);
                model.AppendChild(Sections);
            }

            //  □ StbModel.StbSlabFrames
            if (StbModel.StbSlabFrames != null)
            {
                if (StbModel.StbSlabFrames.StbSlabFrameArrages != null || StbModel.StbSlabFrames.StbSlabFramePatterns != null)
                {
                    XmlElement SlabFrames = xml.CreateElement("StbSlabFrames");
                    WriteXmlElement_StbSlabFrameArranges(xml, SlabFrames);
                    WriteXmlElement_StbSlabFramePatterns(xml, SlabFrames);
                    if (SlabFrames.ChildNodes.Count > 0) model.AppendChild(SlabFrames);
                }
            }

            // StbModelの登録
            StBridge.AppendChild(model);


            // ■ StbFromIfc (フォーマットが決まっていないため未対応)


            // ■ StbExtensions
            WriteXmlElement_StbExtensions(xml, StBridge);


            //保存
            xml.Save(stbFile);

            //解放
            xml = null;
        }
        catch (Exception ex)
        {
            errmsg = "エラーコード： " + ex.HResult + "\r\n" + ex.Message;
            if (element != "") errmsg += "\r\n\r\n" + element + "タグの書き込みでエラーが発生しました。";
        }
        finally
        {
            // 進捗ゲージの消去
            if (form != null)
            {
                do { Application.DoEvents(); } while (sw.ElapsedMilliseconds <= 1000); ;
                sw.Stop();
                GaugeClose();
            }
        }

        return errmsg;
    }


