    private void WriteXmlElement_StbSecColumn_S(XmlDocument xml, XmlElement root)
    {
        //
        // S柱断面情報の書き込み
        //
        element = "S柱断面(StbSecColumn_S)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecColumns_S != null)
        {
            if (StbModel.StbSections.StbSecColumns_S.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecColumns_S.Count; i++)
                {
                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecColumns_S.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecColumn_S");
                    node.SetAttribute("id", StbModel.StbSections.StbSecColumns_S[i].id.ToString());
                    node.SetAttribute("name", StbModel.StbSections.StbSecColumns_S[i].name);
                    if (StbModel.StbSections.StbSecColumns_S[i].floor != "") node.SetAttribute("floor", StbModel.StbSections.StbSecColumns_S[i].floor);
                    if (StbModel.StbSections.StbSecColumns_S[i].kind_column != "") node.SetAttribute("kind_column", StbModel.StbSections.StbSecColumns_S[i].kind_column);
                    node.SetAttribute("direction", StbModel.StbSections.StbSecColumns_S[i].direction.ToString().ToUpper());
                    if (StbModel.StbSections.StbSecColumns_S[i].base_type != "") node.SetAttribute("base_type", StbModel.StbSections.StbSecColumns_S[i].base_type);
                    //子要素(柱鉄骨)
                    if (StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn != null)
                    {
                        for (int j = 0; j < StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn.Length; j++)
                        {
                            XmlElement child = xml.CreateElement("StbSecSteelColumn");
                            child.SetAttribute("pos", StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].pos);
                            child.SetAttribute("shape", StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].shape);
                            child.SetAttribute("strength_main", StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].strength_main);
                            if (StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].strength_web != "") child.SetAttribute("strength_web", StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].strength_web);
                            node.AppendChild(child);

                            // ALLの場合は1レコードのみ出力

                            if (StbModel.StbSections.StbSecColumns_S[i].StbSecSteelColumn[j].pos == "ALL") break;
                        }
                    }
                    //子要素(柱脚)
                    if (StbModel.StbSections.StbSecColumns_S[i].StbSecBaseProduct != null)
                    {
                        XmlElement child = xml.CreateElement("StbSecBaseProduct");
                        child.SetAttribute("product_company", StbModel.StbSections.StbSecColumns_S[i].StbSecBaseProduct.product_company);
                        child.SetAttribute("product_code", StbModel.StbSections.StbSecColumns_S[i].StbSecBaseProduct.product_code);
                        node.AppendChild(child);
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
