                                 || StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_XY != 0
                                 || StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_YX != 0
                                 || StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_YY != 0)
                                {
                                    child.SetAttribute("offset_XX", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_XX.ToString());
                                    child.SetAttribute("offset_XY", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_XY.ToString());
                                    child.SetAttribute("offset_YX", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_YX.ToString());
                                    child.SetAttribute("offset_YY", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeCross.offset_YY.ToString());
                                }
                                SecSteel.AppendChild(child);
                            }
                            //孫要素(Ｔ形断面の鉄骨形状)
                            if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT != null)
                            {
                                XmlElement child = xml.CreateElement("StbSecColumn_SRC_ShapeT");
                                child.SetAttribute("direction_type", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.direction_type);
                                child.SetAttribute("shape_H", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.shape_H);
                                child.SetAttribute("shape_T", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.shape_T);
                                child.SetAttribute("strength_main_H", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_main_H);
                                if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_web_H != "") child.SetAttribute("strength_web_H", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_web_H);
                                child.SetAttribute("strength_main_T", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_main_T);
                                if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_web_T != "") child.SetAttribute("strength_web_T", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.strength_web_T);
                                if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_HX != 0
                                 || StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_HY != 0
                                 || StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_T != 0)
                                {
                                    child.SetAttribute("offset_HX", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_HX.ToString());
                                    child.SetAttribute("offset_HY", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_HY.ToString());
                                    child.SetAttribute("offset_T", StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].StbSecColumn_SRC_ShapeT.offset_T.ToString());
                                }
                                SecSteel.AppendChild(child);
                            }
                            node.AppendChild(SecSteel);

                            // ALLの場合は1レコードのみ出力

                            if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecSteelColumn_SRC[j].pos == "ALL") break;
                        }
                    }
                    //子要素(柱脚)
                    if (StbModel.StbSections.StbSecColumns_SRC[i].StbSecBaseProduct != null)
                    {
                        XmlElement child = xml.CreateElement("StbSecBaseProduct");
                        child.SetAttribute("product_company", StbModel.StbSections.StbSecColumns_SRC[i].StbSecBaseProduct.product_company);
                        child.SetAttribute("product_code", StbModel.StbSections.StbSecColumns_SRC[i].StbSecBaseProduct.product_code);
                        node.AppendChild(child);
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
    private void WriteXmlElement_StbSecColumn_CFT(XmlDocument xml, XmlElement root)
    {
        //
        // CFT柱断面情報の書き込み
        //
        element = "CFT柱断面(StbSecColumn_CFT)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecColumns_CFT != null)
        {
            if (StbModel.StbSections.StbSecColumns_CFT.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecColumns_CFT.Count; i++)
                {
                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecColumns_CFT.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecColumn_CFT");
                    node.SetAttribute("id", StbModel.StbSections.StbSecColumns_CFT[i].id.ToString());
                    node.SetAttribute("name", StbModel.StbSections.StbSecColumns_CFT[i].name);
                    if (StbModel.StbSections.StbSecColumns_CFT[i].floor != "") node.SetAttribute("floor", StbModel.StbSections.StbSecColumns_CFT[i].floor);
                    if (StbModel.StbSections.StbSecColumns_CFT[i].kind_column != "") node.SetAttribute("kind_column", StbModel.StbSections.StbSecColumns_CFT[i].kind_column);
                    if (StbModel.StbSections.StbSecColumns_CFT[i].strength_concrete != "") node.SetAttribute("strength_concrete", StbModel.StbSections.StbSecColumns_CFT[i].strength_concrete);
                    node.SetAttribute("direction", StbModel.StbSections.StbSecColumns_CFT[i].direction.ToString().ToUpper());
                    if (StbModel.StbSections.StbSecColumns_CFT[i].base_type != "") node.SetAttribute("base_type", StbModel.StbSections.StbSecColumns_CFT[i].base_type);
                    if (StbModel.StbSections.StbSecColumns_CFT[i].enbedded_length != 0) node.SetAttribute("enbedded_length", StbModel.StbSections.StbSecColumns_CFT[i].enbedded_length.ToString());
                    //子要素(CFT柱鉄骨)
                    if (StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT != null)
                    {
                        for (int j = 0; j < StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT.Length; j++)
                        {
                            XmlElement child = xml.CreateElement("StbSecSteelColumn_CFT");
                            child.SetAttribute("pos", StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT[j].pos);
                            child.SetAttribute("shape", StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT[j].shape);
                            child.SetAttribute("strength_main", StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT[j].strength_main);
                            node.AppendChild(child);

                            // ALLの場合は1レコードのみ出力

                            if (StbModel.StbSections.StbSecColumns_CFT[i].StbSecSteelColumn_CFT[j].pos == "ALL") break;
                        }
                    }
                    //子要素(柱脚)
                    if (StbModel.StbSections.StbSecColumns_CFT[i].StbSecBaseProduct != null)
                    {
                        XmlElement child = xml.CreateElement("StbSecBaseProduct");
                        child.SetAttribute("product_company", StbModel.StbSections.StbSecColumns_CFT[i].StbSecBaseProduct.product_company);
                        child.SetAttribute("product_code", StbModel.StbSections.StbSecColumns_CFT[i].StbSecBaseProduct.product_code);
                        node.AppendChild(child);
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
