                     || StbModel.StbSections.StbSecBeams_RC[i].depth_cover_top != 0 || StbModel.StbSections.StbSecBeams_RC[i].depth_cover_bottom != 0)
                    {
                        node.SetAttribute("depth_cover_left", StbModel.StbSections.StbSecBeams_RC[i].depth_cover_left.ToString());
                        node.SetAttribute("depth_cover_right", StbModel.StbSections.StbSecBeams_RC[i].depth_cover_right.ToString());
