                        node.SetAttribute("center_reinforcement_bottom", StbModel.StbSections.StbSecBeams_RC[i].center_reinforcement_bottom.ToString());
                    }
                    if (StbModel.StbSections.StbSecBeams_RC[i].bar_length_start != 0 || StbModel.StbSections.StbSecBeams_RC[i].bar_length_end != 0)
                    {
                        node.SetAttribute("bar_length_start", StbModel.StbSections.StbSecBeams_RC[i].bar_length_start.ToString());
                        node.SetAttribute("bar_length_end", StbModel.StbSections.StbSecBeams_RC[i].bar_length_end.ToString());
                    }
                    //子要素(形状)
                    if (StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure != null)
