                            child.SetAttribute("width_start", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecTaper.width_start.ToString());
                            child.SetAttribute("depth_start", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecTaper.depth_start.ToString());
                            child.SetAttribute("width_end", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecTaper.width_end.ToString());
