                        if (StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch != null)
                        {
                            XmlElement child = xml.CreateElement("StbSecHaunch");
                            child.SetAttribute("width_start", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.width_start.ToString());
                            child.SetAttribute("depth_start", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.depth_start.ToString());
                            child.SetAttribute("width_center", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.width_center.ToString());
                            child.SetAttribute("depth_center", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.depth_center.ToString());
                            child.SetAttribute("width_end", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.width_end.ToString());
                            child.SetAttribute("depth_end", StbModel.StbSections.StbSecBeams_RC[i].StbSecFigure.StbSecHaunch.depth_end.ToString());
                            SecFigure.AppendChild(child);
                        }
                        //(形状登録)
                        node.AppendChild(SecFigure);
                    }
                    //子要素(配筋)
                    if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement != null)
                    {
                        XmlElement SecBar = xml.CreateElement("StbSecBar_Arrangement");
                        //(梁全断面同一配筋)
                        if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section != null)
                        {
                            XmlElement child = xml.CreateElement("StbSecBeam_Same_Section");
                            child.SetAttribute("count_main_top_1st", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_top_1st.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_top_2nd != 0) child.SetAttribute("count_main_top_2nd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_top_2nd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_top_3rd != 0) child.SetAttribute("count_main_top_3rd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_top_3rd.ToString());
                            child.SetAttribute("count_main_bottom_1st", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_bottom_1st.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_bottom_2nd != 0) child.SetAttribute("count_main_bottom_2nd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_bottom_2nd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_bottom_3rd != 0) child.SetAttribute("count_main_bottom_3rd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_main_bottom_3rd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_1st != 0) child.SetAttribute("count_2nd_main_top_1st", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_1st.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_2nd != 0) child.SetAttribute("count_2nd_main_top_2nd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_2nd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_3rd != 0) child.SetAttribute("count_2nd_main_top_3rd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_top_3rd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_1st != 0) child.SetAttribute("count_2nd_main_bottom_1st", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_1st.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_2nd != 0) child.SetAttribute("count_2nd_main_bottom_2nd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_2nd.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_3rd != 0) child.SetAttribute("count_2nd_main_bottom_3rd", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_2nd_main_bottom_3rd.ToString());
                            child.SetAttribute("count_stirrup", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_stirrup.ToString());
                            child.SetAttribute("pitch_stirrup", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.pitch_stirrup.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_web != 0) child.SetAttribute("count_web", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_web.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_bar_spacing != 0) child.SetAttribute("count_bar_spacing", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.count_bar_spacing.ToString());
                            if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.pitch_bar_spacing != 0) child.SetAttribute("pitch_bar_spacing", StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Same_Section.pitch_bar_spacing.ToString());
                            SecBar.AppendChild(child);
                        }
                        //(梁断面始端中央終端別配筋)
                        if (StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecBeams_RC[i].StbSecBar_Arrangement.StbSecBeam_Start_Center_End_Section.Length; j++)
                            {
