    private void WriteXmlElement_StbSecBeam_S(XmlDocument xml, XmlElement root)
    {
        //
        // S梁断面情報の書き込み
        //
        element = "S梁断面(StbSecBeam_S)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecBeams_S != null)
        {
            if (StbModel.StbSections.StbSecBeams_S.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecBeams_S.Count; i++)
                {
                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecBeams_S.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecBeam_S");
                    node.SetAttribute("id", StbModel.StbSections.StbSecBeams_S[i].id.ToString());
                    node.SetAttribute("name", StbModel.StbSections.StbSecBeams_S[i].name);
                    if (StbModel.StbSections.StbSecBeams_S[i].floor != "") node.SetAttribute("floor", StbModel.StbSections.StbSecBeams_S[i].floor);
                    if (StbModel.StbSections.StbSecBeams_S[i].kind_beam != "") node.SetAttribute("kind_beam", StbModel.StbSections.StbSecBeams_S[i].kind_beam);
                    node.SetAttribute("isCanti", StbModel.StbSections.StbSecBeams_S[i].isCanti.ToString().ToUpper());
                    node.SetAttribute("isOutIn", StbModel.StbSections.StbSecBeams_S[i].isOutIn.ToString().ToUpper());
                    //子要素(梁鉄骨)
                    if (StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam != null)
                    {
                        for (int j = 0; j < StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam.Length; j++)
                        {
                            if (StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j] != null)
                            {
                                XmlElement child = xml.CreateElement("StbSecSteelBeam");
                                child.SetAttribute("pos", StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].pos);
                                child.SetAttribute("shape", StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].shape);
                                child.SetAttribute("strength_main", StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].strength_main);
                                if (StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].strength_web != "") child.SetAttribute("strength_web", StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].strength_web);
                                node.AppendChild(child);

                                // ALLの場合は1レコードのみ出力

                                if (StbModel.StbSections.StbSecBeams_S[i].StbSecSteelBeam[j].pos == "ALL") break;
                            }
                        }
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
