    private void WriteXmlElement_StbSecBrace_S(XmlDocument xml, XmlElement root)
    {
        //
        // Sブレース断面情報の書き込み
        //
        element = "Sブレース断面(StbSecBrace_S)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecBraces_S != null)
        {
            if (StbModel.StbSections.StbSecBraces_S.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecBraces_S.Count; i++)
                {
                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecBraces_S.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecBrace_S");
                    node.SetAttribute("id", StbModel.StbSections.StbSecBraces_S[i].id.ToString());
                    node.SetAttribute("name", StbModel.StbSections.StbSecBraces_S[i].name);
                    if (StbModel.StbSections.StbSecBraces_S[i].floor != "") node.SetAttribute("floor", StbModel.StbSections.StbSecBraces_S[i].floor);
                    if (StbModel.StbSections.StbSecBraces_S[i].kind_brace != "") node.SetAttribute("kind_brace", StbModel.StbSections.StbSecBraces_S[i].kind_brace);
                    //子要素(梁鉄骨)
                    if (StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace != null)
                    {
                        for (int j = 0; j < StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace.Length; j++)
                        {
                            if (StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j] != null)
                            {
                                XmlElement child = xml.CreateElement("StbSecSteelBrace");
                                child.SetAttribute("pos", StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].pos);
                                child.SetAttribute("shape", StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].shape);
                                child.SetAttribute("strength_main", StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].strength_main);
                                if (StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].strength_web != "") child.SetAttribute("strength_web", StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].strength_web);
                                node.AppendChild(child);

                                // ALLの場合は1レコードのみ出力

                                if (StbModel.StbSections.StbSecBraces_S[i].StbSecSteelBrace[j].pos == "ALL") break;
                            }
                        }
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
