                            bool VerticalOutsideALL = false;
                            bool VerticalInsideALL = false;
                            bool HorizontalOutsideALL = false;
                            bool HorizontalInsideALL = false;
                            for (int j = 0; j < StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside.Length; j++)
                            {
                                if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j] != null)
                                {
                                    do
                                    {
                                        // pos2が[ALL]の場合は1レコードのみ出力

                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "VERTICAL_OUTSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL" && VerticalOutsideALL) break;
                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "VERTICAL_INSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL" && VerticalInsideALL) break;
                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "HORIZONTAL_OUTSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL" && HorizontalOutsideALL) break;
                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "HORIZONTAL_INSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL" && HorizontalInsideALL) break;

                                        XmlElement child = xml.CreateElement("StbSecInside_And_Outside");
                                        child.SetAttribute("pos", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos);
                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2 != "") child.SetAttribute("pos2", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2);
                                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].strength);
                                        child.SetAttribute("D", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].D);
                                        child.SetAttribute("pitch", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pitch.ToString());
                                        SecBar.AppendChild(child);
                                    } while (false);
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "VERTICAL_OUTSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL") VerticalOutsideALL = true;
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "VERTICAL_INSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL") VerticalInsideALL = true;
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "HORIZONTAL_OUTSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL") HorizontalOutsideALL = true;
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos.ToUpper() == "HORIZONTAL_INSIDE" && StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecInside_And_Outside[j].pos2.ToUpper() == "ALL") HorizontalInsideALL = true;
                                }
                            }
                        }
                        //(端部補強配筋)
                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge.Length; j++)
                            {
                                if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j] != null)
                                {
                                    XmlElement child = xml.CreateElement("StbSecWallEdge");
                                    child.SetAttribute("pos", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j].pos);
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j].D);
                                    child.SetAttribute("count", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecWallEdge[j].count.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(壁開口配筋)
                        if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall.Length; j++)
                            {
                                if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j] != null)
                                {
                                    XmlElement child = xml.CreateElement("StbSecOpen_Wall");
                                    child.SetAttribute("pos", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].pos);
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].D);
                                    child.SetAttribute("count", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].count.ToString());
                                    if (StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].length != 0) child.SetAttribute("length", StbModel.StbSections.StbSecWalls_RC[i].StbSecBar_Arrangement.StbSecOpen_Wall[j].length.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(配筋登録)
                        node.AppendChild(SecBar);
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
    private void WriteXmlElement_StbSecFoundation_RC(XmlDocument xml, XmlElement root)
    {
        //
        // RC基礎断面情報の書き込み
