                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecFoundations_RC.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecFoundation_RC");
                    node.SetAttribute("id", StbModel.StbSections.StbSecFoundations_RC[i].id.ToString());
