                    if (StbModel.StbSections.StbSecFoundations_RC[i].strength_concrete != "") node.SetAttribute("strength_concrete", StbModel.StbSections.StbSecFoundations_RC[i].strength_concrete);
                    if (StbModel.StbSections.StbSecFoundations_RC[i].depth_cover_top != 0
                     || StbModel.StbSections.StbSecFoundations_RC[i].depth_cover_bottom != 0
                     || StbModel.StbSections.StbSecFoundations_RC[i].depth_cover_side != 0)
                    {
