                                    child.SetAttribute("D", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecThreeWay[j].D);
                                    child.SetAttribute("count", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecThreeWay[j].count.ToString());
                                    SecBar.AppendChild(child);
                                }
