                        }
                        //(連続配筋)
                        if (StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous.Length; j++)
                            {
