                                    if (StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].D);
                                    if (StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].count != 0) child.SetAttribute("count", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].count.ToString());
                                    if (StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].pitch != 0) child.SetAttribute("pitch", StbModel.StbSections.StbSecFoundations_RC[i].StbSecBar_Arrangement.StbSecContinuous[j].pitch.ToString());
                                    SecBar.AppendChild(child);
