    private void WriteXmlElement_StbSecPile_RC(XmlDocument xml, XmlElement root)
    {
        //
        // RC杭断面情報の書き込み
        //
        element = "RC杭断面(StbSecPile_RC)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecPiles_RC != null)
        {
            if (StbModel.StbSections.StbSecPiles_RC.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecPiles_RC.Count; i++)
                {
                    GaugePercent(element + " 書き込み", (int)((double)(i + 1) / (double)(StbModel.StbSections.StbSecPiles_RC.Count) * 100));
                    XmlElement node = xml.CreateElement("StbSecPile_RC");
                    node.SetAttribute("id", StbModel.StbSections.StbSecPiles_RC[i].id.ToString());
                    node.SetAttribute("name", StbModel.StbSections.StbSecPiles_RC[i].name);
                    if (StbModel.StbSections.StbSecPiles_RC[i].strength_concrete != "") node.SetAttribute("strength_concrete", StbModel.StbSections.StbSecPiles_RC[i].strength_concrete);
                    if (StbModel.StbSections.StbSecPiles_RC[i].depth_cover != 0 || StbModel.StbSections.StbSecPiles_RC[i].depth_cover_top != 0)
                    {
                        node.SetAttribute("depth_cover", StbModel.StbSections.StbSecPiles_RC[i].depth_cover.ToString());
                        node.SetAttribute("depth_cover_top", StbModel.StbSections.StbSecPiles_RC[i].depth_cover_top.ToString());
