    private void WriteXmlElement_StbSecParapet_RC(XmlDocument xml, XmlElement root)
    {
        //
        // RCパラペット断面情報の書き込み
        //
        element = "RCパラペット断面(StbSecParapet_RC)";
        GaugePercent(element + " 書き込み", 0);

        if (StbModel.StbSections.StbSecParapets_RC != null)
        {
            if (StbModel.StbSections.StbSecParapets_RC.Count > 0)
            {
                for (int i = 0; i < StbModel.StbSections.StbSecParapets_RC.Count; i++)
