                    node.SetAttribute("isTip_line", StbModel.StbSections.StbSecParapets_RC[i].isTip_line.ToString().ToUpper());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_T != 0) node.SetAttribute("depth_T", StbModel.StbSections.StbSecParapets_RC[i].depth_T.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_H != 0) node.SetAttribute("depth_H", StbModel.StbSections.StbSecParapets_RC[i].depth_H.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_T1 != 0) node.SetAttribute("depth_T1", StbModel.StbSections.StbSecParapets_RC[i].depth_T1.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_H1 != 0) node.SetAttribute("depth_H1", StbModel.StbSections.StbSecParapets_RC[i].depth_H1.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_H2 != 0) node.SetAttribute("depth_H2", StbModel.StbSections.StbSecParapets_RC[i].depth_H2.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_H3 != 0) node.SetAttribute("depth_H3", StbModel.StbSections.StbSecParapets_RC[i].depth_H3.ToString());
                    if (StbModel.StbSections.StbSecParapets_RC[i].strength_concrete != "") node.SetAttribute("strength_concrete", StbModel.StbSections.StbSecParapets_RC[i].strength_concrete);
                    if (StbModel.StbSections.StbSecParapets_RC[i].depth_cover_outside != 0 || StbModel.StbSections.StbSecParapets_RC[i].depth_cover_inside != 0)
                    {
                        node.SetAttribute("depth_cover_outside", StbModel.StbSections.StbSecParapets_RC[i].depth_cover_outside.ToString());
                        node.SetAttribute("depth_cover_inside", StbModel.StbSections.StbSecParapets_RC[i].depth_cover_inside.ToString());
                    }
                    //子要素(配筋)
                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement != null)
                    {
                        XmlElement SecBar = xml.CreateElement("StbSecBar_Arrangement");
