                                    child.SetAttribute("D", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecSingle[j].D);
                                    child.SetAttribute("pitch", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecSingle[j].pitch.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(千鳥配筋)
                        if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag.Length; j++)
                            {
