                                    child.SetAttribute("pos", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag[j].pos);
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag[j].D);
                                    child.SetAttribute("pitch", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecZigzag[j].pitch.ToString());
                                    SecBar.AppendChild(child);
