                        }
                        //(ダブル配筋)
                        if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net.Length; j++)
                            {
