                                    child.SetAttribute("pos", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net[j].pos);
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net[j].D);
                                    child.SetAttribute("pitch", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecDouble_Net[j].pitch.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(先端補強筋（アゴ筋）)
                        if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip.Length; j++)
                            {
                                if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j] != null)
                                {
                                    XmlElement child = xml.CreateElement("StbSecParapetTip");
                                    child.SetAttribute("pos", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].pos);
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].D);
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].pitch != 0) child.SetAttribute("pitch", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].pitch.ToString());
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].count != 0) child.SetAttribute("count", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetTip[j].count.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(端部補強筋)
                        if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge != null)
                        {
                            for (int j = 0; j < StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge.Length; j++)
                            {
                                if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j] != null)
                                {
                                    XmlElement child = xml.CreateElement("StbSecParapetEdge");
                                    child.SetAttribute("pos", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j].pos);
                                    if (StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j].strength != "") child.SetAttribute("strength", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j].strength);
                                    child.SetAttribute("D", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j].D);
                                    child.SetAttribute("count", StbModel.StbSections.StbSecParapets_RC[i].StbSecBar_Arrangement.StbSecParapetEdge[j].count.ToString());
                                    SecBar.AppendChild(child);
                                }
                            }
                        }
                        //(配筋登録)
                        node.AppendChild(SecBar);
                    }

                    //この要素をルートに登録
                    root.AppendChild(node);
                }
                GaugePercent(element + " 書き込み", 100);
            }
        }
    }
