                    if (StbModel.StbSlabFrames.StbSlabFramePatterns.StbSlabFramePattern[i].level_slab != 0) node.SetAttribute("level_slab", StbModel.StbSlabFrames.StbSlabFramePatterns.StbSlabFramePattern[i].level_slab.ToString());
