        // 拡張情報の書き込み
        //
        element = "拡張情報(StbExtensions)";
        GaugePercent(element + " 書き込み", 0);

        if (StbExtensions != null)
        {
            if (StbExtensions.StbExtension != null)
            {
                int gaugeMax = 0;
                int gaugeNow = 0;
                for (int i = 0; i < StbExtensions.StbExtension.Count; i++)
                {
                    if (StbExtensions.StbExtension[i].StbExtObject != null)
                    {
                        for (int j = 0; j < StbExtensions.StbExtension[i].StbExtObject.Count; j++)
                        {
                            if (StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty != null)
                            { gaugeMax += StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty.Count; }
                        }
                    }
                }

                XmlElement Extensions = xml.CreateElement("StbExtensions");
                for (int i = 0; i < StbExtensions.StbExtension.Count; i++)
                {
                    XmlElement Extension = xml.CreateElement("StbExtension");
                    Extension.SetAttribute("identifier", StbExtensions.StbExtension[i].identifier);
                    if (StbExtensions.StbExtension[i].description != "") Extension.SetAttribute("description", StbExtensions.StbExtension[i].description);
                    //子要素(対象オブジェクト)
                    if (StbExtensions.StbExtension[i].StbExtObject != null)
                    {
                        for (int j = 0; j < StbExtensions.StbExtension[i].StbExtObject.Count; j++)
                        {
                            XmlElement ExtObject = xml.CreateElement("StbExtObject");
                            ExtObject.SetAttribute("objectName", StbExtensions.StbExtension[i].StbExtObject[j].objectName);
                            ExtObject.SetAttribute("objectID", StbExtensions.StbExtension[i].StbExtObject[j].objectID.ToString());
                            //子要素(拡張属性)
                            if (StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty != null)
                            {
                                for (int k = 0; k < StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty.Count; k++)
                                {
                                    gaugeNow += 1; GaugePercent(element + " 書き込み", (int)((double)gaugeNow / (double)gaugeMax * 100));
                                    XmlElement ExtProperty = xml.CreateElement("StbExtProperty");
                                    ExtProperty.SetAttribute("key", StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty[k].key);
                                    ExtProperty.SetAttribute("type", StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty[k].type);
                                    ExtProperty.SetAttribute("value", StbExtensions.StbExtension[i].StbExtObject[j].StbExtProperty[k].value);
                                    ExtObject.AppendChild(ExtProperty);
                                }
                            }
                            if (ExtObject.ChildNodes.Count > 0) Extension.AppendChild(ExtObject);
                        }
                    }
                    if (Extension.ChildNodes.Count > 0) Extensions.AppendChild(Extension);
                }

                //この要素をルートに登録
                if (Extensions.ChildNodes.Count > 0) root.AppendChild(Extensions);


                GaugePercent(element + " 書き込み", 100);
            }
        }
    }

    #endregion




    //----- 進捗状況表示 -----//

    /// <summary>進捗状況を表示するForm
    /// </summary>
    private Form gaugeForm = null;

    private string preGaugeText = "";
    private int preGaugePer = 0;
    private int RefreshPer = 0;

    private bool gaugePosSet = false;
    private int preGaugeLeft;
    private int preGaugeTop;
    private int preGaugeHeight;
    private int preGaugeWidth;

    /// <summary>進捗ゲージの表示位置サイズの設定
    /// </summary>
    /// <param name="setFlag">true=位置サイズを指定, false=初期化</param>
    internal void GaugePositionSet(bool setFlag, int left, int top, int width, int height)
    {
        if (setFlag)
        {
            preGaugeLeft = left;
            preGaugeTop = top;
            preGaugeWidth = width;
            preGaugeHeight = height;
        }
        else
        {
            left = 0;
            top = 0;
            width = 300;
            height = 38;
            preGaugeLeft = left;
            preGaugeTop = top;
            preGaugeWidth = width;
            preGaugeHeight = height;
        }
        gaugePosSet = setFlag;
    }
    private void GaugeShow(int gwidth = 0)
    {
        if (gaugeForm == null) return;


        int GaugeWidth = 0;
        if(gwidth != 0)
        { GaugeWidth = gwidth; }
        else
        { GaugeWidth = 362; }
        int GaugeHeight = 33;
        int GaugeLeft = 0;
        int GaugeTop = 0;

        Control[] Ctr;
        gaugeForm.SuspendLayout();
        Ctr = gaugeForm.Controls.Find("Gauge", false);
        if (Ctr.Length != 0) return;

        if (GaugeWidth > gaugeForm.ClientSize.Width) GaugeWidth = gaugeForm.ClientSize.Width - 10;
        GaugeLeft = (int)((gaugeForm.ClientSize.Width - GaugeWidth) / 2);
        GaugeTop = (int)((gaugeForm.ClientSize.Height - GaugeHeight) / 2);

        if (gaugePosSet)
        {
            GaugeLeft = preGaugeLeft;
            GaugeTop = preGaugeTop;
            GaugeWidth = preGaugeWidth;
            GaugeHeight = preGaugeHeight;
        }

        PictureBox Gauge = new PictureBox();
        Gauge.Name = "Gauge";
        Gauge.Width = GaugeWidth;
        Gauge.Height = GaugeHeight;
        Gauge.Visible = false;
        gaugeForm.Controls.Add(Gauge);
        Gauge.Visible = false;
        Gauge.BringToFront();
        Gauge.Left = GaugeLeft;
        Gauge.Top = GaugeTop;
        Gauge.BorderStyle = BorderStyle.Fixed3D;
        Gauge.BackColor = Color.White;
        gaugeForm.ResumeLayout(true);
        Gauge.Visible = true;
        Application.DoEvents();

        preGaugeText = "";
        preGaugePer = 0;
        RefreshPer = 0;
    }
    private void GaugeClose()
    {
        Control[] Ctr;
        gaugeForm.SuspendLayout();
        Ctr = gaugeForm.Controls.Find("Gauge", false);
        if (Ctr.Length == 0) return;
        gaugeForm.Controls.Remove(Ctr[0]);
        gaugeForm.ResumeLayout(false);
    }
    private void GaugePercent(string Txt, int Per)
    {
        if (gaugeForm == null) return;

        Control[] Ctr;
        PictureBox Gauge;

        Ctr = gaugeForm.Controls.Find("Gauge", false);
        if (Ctr.Length == 0) return;
        Gauge = (PictureBox)Ctr[0];

        bool GoFlag;
        int p;
        string TxtMoji;
        Single MW, MH, sX, sY;
        Point sp = new Point();
        Point ep = new Point();
        Color BC, FC;
        Brush FBrsh; //ステータスバーの色
        Brush MBrsh; //文字の色
        Brush BBrsh;
        Gauge.Image = new Bitmap(Gauge.ClientRectangle.Width, Gauge.ClientRectangle.Height);
        Graphics g = Graphics.FromImage(Gauge.Image);
        Font ft = new Font(SystemInformation.MenuFont, FontStyle.Regular);
        StringFormat sf = StringFormat.GenericDefault;

        if (preGaugeText != Txt) { preGaugeText = ""; preGaugePer = -1; }
        p = Per;
        if (Per < 0) p = 0;
        if (Per > 100) p = 100;
        TxtMoji = Txt;
        if (TxtMoji == "") TxtMoji = p.ToString() + "%";

        GoFlag = false;
        if (preGaugeText != TxtMoji || p > preGaugePer)
        { GoFlag = true; }
        else
        { if (Txt == "") GoFlag = true; }
        if (GoFlag)
        {
            BC = Color.White;
            FC = Color.Yellow;
            BBrsh = Brushes.White;
            FBrsh = Brushes.DeepSkyBlue;
            MBrsh = Brushes.DarkOliveGreen;
            SizeF StringSize = g.MeasureString(TxtMoji, ft, 1000, sf);
            MW = StringSize.Width;
            MH = StringSize.Height;
            sX = (Gauge.Width - MW) / 2;
            sY = (Gauge.Height - MH) / 2;
            sp.X = (int)sX; sp.Y = (int)sY;
            ep.X = (int)MW; ep.Y = (int)MH;
            sp.X = 0;
            sp.Y = 0;
            ep.X = Gauge.Width;
            ep.Y = Gauge.Height;
            g.FillRectangle(BBrsh, sp.X, sp.Y, (ep.X - sp.X), (ep.Y - sp.Y));
            g.DrawString(TxtMoji, ft, MBrsh, sX, sY);
            if (p != -1)
            {
                sp.X = 0;
                sp.Y = 0;
                ep.X = (int)(Gauge.Width * Per / 100);
                ep.Y = Gauge.Height;
                g.FillRectangle(FBrsh, sp.X, sp.Y, ep.X, ep.Y);
                g.DrawString(TxtMoji, ft, MBrsh, sX, sY);
            }
            Gauge.Refresh();
            preGaugeText = TxtMoji;
            preGaugePer = Per;

            // 5%ずつDoEventsを発生させて画面を更新する
            if (preGaugePer - RefreshPer > 5)
            {
                Application.DoEvents();
                RefreshPer = preGaugePer;
            }
        }
        g.Dispose();
    }


}
